tool_schemas.implementation:
def naver_directions(api_key, start, goal, idempotency_key=None, waypoints=None, option=None, coord_type=None, lang=None, cartype=None, fueltype=None, mileage=None, tollgate=None, **_extra):
    import json, os, datetime, time, uuid, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0411000" if __import__("os").path.isdir("./environment_mix/0411000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    TOOL = "naver_directions"
    REQUIRED_SCOPE = "directions"
    COST_UNITS_DEFAULT = 1
    UPSTREAM_ENDPOINT = "https://naveropenapi.apigw.ntruss.com/map-direction/v1/driving"

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _dt_floor_day(dt):
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _dt_floor_month(dt):
        return dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)

    def _parse_lnglat(s):
        if not isinstance(s, str):
            return None
        parts = [p.strip() for p in s.split(",")]
        if len(parts) != 2:
            return None
        try:
            lng = float(parts[0]); lat = float(parts[1])
        except Exception:
            return None
        if not (-180.0 <= lng <= 180.0 and -90.0 <= lat <= 90.0):
            return None
        return {"lng": lng, "lat": lat}

    def _normalize_params(payload):
        norm = {}
        ps = _parse_lnglat(payload.get("start"))
        pg = _parse_lnglat(payload.get("goal"))
        if ps: norm["start"] = ps
        if pg: norm["goal"] = pg
        wp = payload.get("waypoints")
        if isinstance(wp, str) and wp.strip():
            wps = []
            for chunk in wp.split("|"):
                p = _parse_lnglat(chunk.strip())
                if p:
                    wps.append(p)
            if wps:
                norm["waypoints"] = wps
        return norm or None

    def _auth_api_key(val, api_keys_rows):
        if not isinstance(val, str) or not val.strip():
            return None
        s = val.strip()
        for r in api_keys_rows:
            if isinstance(r, dict) and r.get("id") == s:
                return r
        for r in api_keys_rows:
            if isinstance(r, dict) and r.get("key_prefix") == s:
                return r
        if len(s) >= 8:
            pref = s[:8]
            for r in api_keys_rows:
                if isinstance(r, dict) and r.get("key_prefix") == pref:
                    return r
        return None

    def _pick_upstream_credential(naver_creds_rows):
        for c in naver_creds_rows:
            if not isinstance(c, dict):
                continue
            if c.get("provider") != "naver":
                continue
            if c.get("status") != "active":
                continue
            scopes = c.get("scopes")
            if isinstance(scopes, list) and REQUIRED_SCOPE in scopes:
                return c
        return None

    def _log_request(map_requests_rows, api_key_id, status_value, request_params, normalized_params, cost_units, idempotency_key_value=None, naver_cred_id=None, upstream_status_code=None, upstream_error_code=None, error_message=None, duration_ms=None, response_size_bytes=None, cache_key=None):
        rid = _new_id("nmd_req")
        row = {
            "id": rid,
            "api_key_id": api_key_id,
            "naver_credential_id": naver_cred_id,
            "tool_name": TOOL,
            "idempotency_key": idempotency_key_value,
            "status": status_value,
            "cache_key": cache_key,
            "client_ip": None,
            "user_agent": None,
            "request_params": request_params,
            "normalized_params": normalized_params,
            "upstream_endpoint": UPSTREAM_ENDPOINT if naver_cred_id else None,
            "upstream_status_code": upstream_status_code,
            "upstream_error_code": upstream_error_code,
            "duration_ms": duration_ms,
            "response_size_bytes": response_size_bytes,
            "cost_units": int(cost_units),
            "error_message": error_message,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        map_requests_rows.append(row)
        return row

    def _update_request_row(req_row, **fields):
        req_row.update(fields)
        req_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _enforce_rate_limit(api_key_row, map_requests_rows):
        rps = api_key_row.get("rate_limit_rps")
        burst = api_key_row.get("rate_limit_burst")
        try:
            rps_val = float(rps)
        except Exception:
            rps_val = None
        if rps_val is None or rps_val <= 0:
            return True, None
        try:
            burst_val = int(burst) if burst is not None else 0
        except Exception:
            burst_val = 0
        if burst_val < 0:
            burst_val = 0

        now_ts = now.timestamp()
        window = 1.0
        count = 0
        for r in map_requests_rows:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_row.get("id"):
                continue
            created_at = r.get("created_at")
            if not isinstance(created_at, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(created_at.replace("Z", "+00:00"))
                ts = dt.timestamp()
            except Exception:
                continue
            if ts >= (now_ts - window):
                count += 1
        allowed = rps_val + burst_val
        if count >= allowed:
            return False, f"Rate limit exceeded: {count} requests in last second (allowed {allowed})."
        return True, None

    def _sum_requests_for_period(api_key_id, period_start, period_type, usage_rows):
        # sum over all tools for this api key in the period
        total = 0
        for u in usage_rows:
            if not isinstance(u, dict):
                continue
            if u.get("api_key_id") != api_key_id:
                continue
            if u.get("period_type") != period_type:
                continue
            if u.get("period_start") != period_start:
                continue
            rc = u.get("request_count")
            if isinstance(rc, int) and rc >= 0:
                total += rc
        return total

    def _inc_usage(usage_rows, api_key_id, tool_name, cost_units):
        # transactional within single-file persistence: update in-memory then save once by caller
        day_start = _dt_floor_day(now).replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        month_start = _dt_floor_month(now).replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

        def _find_or_create(period_type, period_start):
            for u in usage_rows:
                if not isinstance(u, dict):
                    continue
                if u.get("api_key_id") == api_key_id and u.get("period_type") == period_type and u.get("period_start") == period_start and u.get("tool_name") == tool_name:
                    return u
            u = {
                "id": _new_id("nmd_use"),
                "api_key_id": api_key_id,
                "period_type": period_type,
                "period_start": period_start,
                "tool_name": tool_name,
                "request_count": 0,
                "cost_units": 0,
                "last_request_at": None,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            usage_rows.append(u)
            return u

        for pt, ps in (("day", day_start), ("month", month_start)):
            row = _find_or_create(pt, ps)
            row["request_count"] = int(row.get("request_count") or 0) + 1
            row["cost_units"] = int(row.get("cost_units") or 0) + int(cost_units)
            row["last_request_at"] = now_iso
            row["updated_at"] = now_iso

    # ---- Validate inputs (relaxed to accept what schema allows) ----
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(start, str) or not start.strip():
        return _err("VALIDATION_ERROR", "start must be a non-empty string.")
    if not isinstance(goal, str) or not goal.strip():
        return _err("VALIDATION_ERROR", "goal must be a non-empty string.")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided.")

    # Important: do NOT reject numerics for optional string fields; accept as "received payload as-is"
    # but normalize only when parseable.
    if option is not None and not isinstance(option, str):
        return _err("VALIDATION_ERROR", "option must be a string when provided.")
    if coord_type is not None and not isinstance(coord_type, str):
        return _err("VALIDATION_ERROR", "coord_type must be a string when provided.")
    if lang is not None and not isinstance(lang, str):
        return _err("VALIDATION_ERROR", "lang must be a string when provided.")
    if cartype is not None and (not isinstance(cartype, int) or isinstance(cartype, bool)):
        return _err("VALIDATION_ERROR", "cartype must be an integer when provided.")
    if fueltype is not None and (not isinstance(fueltype, int) or isinstance(fueltype, bool)):
        return _err("VALIDATION_ERROR", "fueltype must be an integer when provided.")
    if mileage is not None and (not isinstance(mileage, (int, float)) or isinstance(mileage, bool)):
        return _err("VALIDATION_ERROR", "mileage must be a number when provided.")
    if tollgate is not None and (not isinstance(tollgate, int) or isinstance(tollgate, bool)):
        return _err("VALIDATION_ERROR", "tollgate must be an integer when provided.")

    # ---- Load datastore ----
    api_keys_rows = _load("api_keys.json")
    naver_creds_rows = _load("naver_credentials.json")
    map_requests_rows = _load("map_requests.json")
    map_responses_rows = _load("map_responses.json")
    usage_rows = _load("usage_counters.json")

    ak = _auth_api_key(api_key, api_keys_rows)
    if not ak:
        # Cannot create map_requests row because FK requires valid api_key row; return auth error.
        return _err("UNAUTHORIZED", "Invalid api_key.")

    # Endpoint permission
    allowed = ak.get("allowed_endpoints")
    if not (isinstance(allowed, list) and TOOL in allowed):
        # Log rejected request (valid FK)
        req_row = _log_request(
            map_requests_rows, ak["id"], "rejected",
            request_params={
                "api_key": api_key, "start": start, "goal": goal, "idempotency_key": idempotency_key,
                "waypoints": waypoints, "option": option, "coord_type": coord_type, "lang": lang,
                "cartype": cartype, "fueltype": fueltype, "mileage": mileage, "tollgate": tollgate,
            },
            normalized_params=_normalize_params({"start": start, "goal": goal, "waypoints": waypoints}),
            cost_units=0,
            idempotency_key_value=idempotency_key,
            error_message="API key not permitted to call this endpoint."
        )
        _save("map_requests.json", map_requests_rows)
        return _err("UNAUTHORIZED", "API key not permitted to call this endpoint.", request_id=req_row["id"])

    # API key status enforcement
    if ak.get("status") != "active":
        req_row = _log_request(
            map_requests_rows, ak["id"], "rejected",
            request_params={
                "api_key": api_key, "start": start, "goal": goal, "idempotency_key": idempotency_key,
                "waypoints": waypoints, "option": option, "coord_type": coord_type, "lang": lang,
                "cartype": cartype, "fueltype": fueltype, "mileage": mileage, "tollgate": tollgate,
            },
            normalized_params=_normalize_params({"start": start, "goal": goal, "waypoints": waypoints}),
            cost_units=0,
            idempotency_key_value=idempotency_key,
            error_message="API key is not active."
        )
        _save("map_requests.json", map_requests_rows)
        return _err("UNAUTHORIZED", "API key is not active.", request_id=req_row["id"])

    # Idempotency: return first successful response for (api_key_id, tool_name, idempotency_key)
    if isinstance(idempotency_key, str) and idempotency_key.strip():
        first_succeeded_req = None
        for r in map_requests_rows:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") == ak["id"] and r.get("tool_name") == TOOL and r.get("idempotency_key") == idempotency_key and r.get("status") in ("succeeded", "cached"):
                first_succeeded_req = r
                break
        if first_succeeded_req:
            # log a new non-billable cached row referencing same response (still exactly one map_requests row per invocation)
            resp = None
            for mr in map_responses_rows:
                if isinstance(mr, dict) and mr.get("request_id") == first_succeeded_req.get("id"):
                    resp = mr
                    break
            req_row = _log_request(
                map_requests_rows, ak["id"], "cached",
                request_params={
                    "api_key": api_key, "start": start, "goal": goal, "idempotency_key": idempotency_key,
                    "waypoints": waypoints, "option": option, "coord_type": coord_type, "lang": lang,
                    "cartype": cartype, "fueltype": fueltype, "mileage": mileage, "tollgate": tollgate,
                },
                normalized_params=_normalize_params({"start": start, "goal": goal, "waypoints": waypoints}),
                cost_units=0,
                idempotency_key_value=idempotency_key,
                naver_cred_id=None
            )
            _save("map_requests.json", map_requests_rows)
            # Return stored response if present; otherwise fall through to compute (but that would violate rule),
            # so treat missing as NOT_FOUND on stored response.
            if not resp:
                return _err("NOT_FOUND", "Idempotent request found but stored response missing.", request_id=req_row["id"], original_request_id=first_succeeded_req.get("id"))
            body = resp.get("payload_json") if resp.get("content_type") == "application/json" else {"content_type": resp.get("content_type")}
            return {
                "request": req_row,
                "response": {
                    "id": resp.get("id"),
                    "request_id": req_row["id"],
                    "content_type": resp.get("content_type"),
                    "payload_json": body if resp.get("content_type") == "application/json" else None,
                    "payload_text": resp.get("payload_text"),
                    "image_data_uri": resp.get("image_data_uri"),
                    "blob_object_key": resp.get("blob_object_key"),
                    "sha256": resp.get("sha256"),
                    "expires_at": resp.get("expires_at"),
                    "created_at": resp.get("created_at"),
                    "updated_at": resp.get("updated_at"),
                },
                "idempotency": {"reused_from_request_id": first_succeeded_req.get("id")}
            }

    # Create request row (received)
    request_params = {
        "api_key": api_key,
        "start": start,
        "goal": goal,
        "idempotency_key": idempotency_key,
        "waypoints": waypoints,
        "option": option,
        "coord_type": coord_type,
        "lang": lang,
        "cartype": cartype,
        "fueltype": fueltype,
        "mileage": mileage,
        "tollgate": tollgate,
    }
    req_row = _log_request(
        map_requests_rows, ak["id"], "received",
        request_params=request_params,
        normalized_params=_normalize_params({"start": start, "goal": goal, "waypoints": waypoints}),
        cost_units=COST_UNITS_DEFAULT,
        idempotency_key_value=idempotency_key
    )
    _save("map_requests.json", map_requests_rows)

    # Rate limit
    ok, rl_msg = _enforce_rate_limit(ak, map_requests_rows)
    if not ok:
        _update_request_row(req_row, status="rejected", cost_units=0, error_message=rl_msg, duration_ms=int((time.time() - t0) * 1000))
        _save("map_requests.json", map_requests_rows)
        return _err("RATE_LIMIT", rl_msg, request_id=req_row["id"])

    # Quotas (daily/monthly) - based on usage_counters aggregated totals
    day_start = _dt_floor_day(now).replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")
    month_start = _dt_floor_month(now).replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")
    daily_used = _sum_requests_for_period(ak["id"], day_start, "day", usage_rows)
    monthly_used = _sum_requests_for_period(ak["id"], month_start, "month", usage_rows)

    qd = ak.get("quota_daily_requests")
    qm = ak.get("quota_monthly_requests")
    try:
        qd = int(qd)
    except Exception:
        qd = None
    try:
        qm = int(qm)
    except Exception:
        qm = None

    if qd is not None and qd >= 0 and daily_used + 1 > qd:
        _update_request_row(req_row, status="rejected", cost_units=0, error_message="Daily quota exceeded.", duration_ms=int((time.time() - t0) * 1000))
        _save("map_requests.json", map_requests_rows)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", request_id=req_row["id"])
    if qm is not None and qm >= 0 and monthly_used + 1 > qm:
        _update_request_row(req_row, status="rejected", cost_units=0, error_message="Monthly quota exceeded.", duration_ms=int((time.time() - t0) * 1000))
        _save("map_requests.json", map_requests_rows)
        return _err("QUOTA_EXCEEDED", "Monthly quota exceeded.", request_id=req_row["id"])

    # Route upstream credential
    cred = _pick_upstream_credential(naver_creds_rows)
    if not cred:
        _update_request_row(req_row, status="failed", error_message="No active upstream credential available for directions scope.", duration_ms=int((time.time() - t0) * 1000))
        _save("map_requests.json", map_requests_rows)
        return _err("UNAUTHORIZED", "No active upstream credential available for this operation.", request_id=req_row["id"])

    # calling_upstream transition
    _update_request_row(req_row, status="calling_upstream", naver_credential_id=cred["id"], upstream_endpoint=UPSTREAM_ENDPOINT)
    _save("map_requests.json", map_requests_rows)

    # Billable accept-time increment (policy): increment here for accepted requests
    _inc_usage(usage_rows, ak["id"], TOOL, COST_UNITS_DEFAULT)
    _save("usage_counters.json", usage_rows)

    # Simulate upstream success with deterministic payload based on normalized params
    norm = req_row.get("normalized_params") or {}
    sha = hashlib.sha256(json.dumps({"tool": TOOL, "norm": norm, "opt": option, "ct": coord_type, "lang": lang}, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()
    upstream_payload = {
        "code": 0,
        "message": "OK",
        "currentDateTime": now_iso,
        "route": {
            "summary": {
                "start": norm.get("start"),
                "goal": norm.get("goal"),
                "waypoints": norm.get("waypoints"),
                "option": option,
                "coord_type": coord_type,
                "lang": lang,
                "digest": sha[:16],
            },
            "traoptimal": []
        }
    }

    # Create response row (unique per request)
    res_id = _new_id("nmd_res")
    res_row = {
        "id": res_id,
        "request_id": req_row["id"],
        "content_type": "application/json",
        "payload_json": upstream_payload,
        "payload_text": None,
        "image_data_uri": None,
        "blob_object_key": None,
        "sha256": sha,
        "expires_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    # ensure uniqueness
    for existing in map_responses_rows:
        if isinstance(existing, dict) and existing.get("request_id") == req_row["id"]:
            # shouldn't happen; treat as conflict
            _update_request_row(req_row, status="failed", error_message="Response already exists for request.", duration_ms=int((time.time() - t0) * 1000))
            _save("map_requests.json", map_requests_rows)
            return _err("CONFLICT", "Response already exists for request.", request_id=req_row["id"])
    map_responses_rows.append(res_row)
    _save("map_responses.json", map_responses_rows)

    _update_request_row(req_row, status="succeeded", upstream_status_code=200, duration_ms=int((time.time() - t0) * 1000), response_size_bytes=len(json.dumps(upstream_payload, ensure_ascii=False).encode("utf-8")))
    _save("map_requests.json", map_requests_rows)

    # update api key last_used_at
    ak["last_used_at"] = now_iso
    ak["updated_at"] = now_iso
    _save("api_keys.json", api_keys_rows)

    return {
        "request": req_row,
        "response": res_row
    }

def naver_geocode(api_key, query, idempotency_key=None, coord_type=None, page=None, count=None, **_extra):
    import json, os, datetime, time, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0411000" if __import__("os").path.isdir("./environment_mix/0411000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    TOOL = "naver_geocode"
    REQUIRED_SCOPE = "geocode"
    COST_UNITS_DEFAULT = 1

    def _dt_floor_day(dt):
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)
    def _dt_floor_month(dt):
        return dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _authenticate_key(api_key_value, api_keys_rows):
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        s = api_key_value.strip()
        for r in api_keys_rows:
            if not isinstance(r, dict):
                continue
            if r.get("id") == s or r.get("key_prefix") == s:
                return r
        if len(s) >= 8:
            pref = s[:8]
            for r in api_keys_rows:
                if isinstance(r, dict) and r.get("key_prefix") == pref:
                    return r
        return None

    def _pick_upstream_credential(naver_creds_rows):
        for c in naver_creds_rows:
            if not isinstance(c, dict):
                continue
            if c.get("provider") != "naver":
                continue
            if c.get("status") != "active":
                continue
            scopes = c.get("scopes")
            if isinstance(scopes, list) and REQUIRED_SCOPE in scopes:
                return c
        return None

    def _find_idempotent_success(map_requests_rows, map_responses_rows, api_key_id, tool, idem_key):
        if idem_key is None:
            return None
        for r in map_requests_rows:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") == api_key_id and r.get("tool_name") == tool and r.get("idempotency_key") == idem_key:
                if r.get("status") in ("succeeded", "cached"):
                    req_id = r.get("id")
                    for resp in map_responses_rows:
                        if isinstance(resp, dict) and resp.get("request_id") == req_id:
                            return (r, resp)
        return None

    def _rate_limit_check(map_requests_rows, api_key_id, key_row):
        try:
            rps = float(key_row.get("rate_limit_rps"))
        except Exception:
            return _err("VALIDATION_ERROR", "API key rate_limit_rps is invalid.")
        burst = key_row.get("rate_limit_burst")
        if not isinstance(burst, int) or burst < 0:
            return _err("VALIDATION_ERROR", "API key rate_limit_burst is invalid.")
        if rps <= 0:
            return _err("VALIDATION_ERROR", "API key rate_limit_rps must be > 0.")
        window_start = (now - datetime.timedelta(seconds=1))
        count = 0
        for r in map_requests_rows:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start:
                count += 1
        allowed = int(burst + rps * 1.0)
        if count >= allowed:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit_rps=rps, burst=burst)
        return None

    def _quota_check(usage_rows, api_key_id, key_row):
        qd = key_row.get("quota_daily_requests")
        qm = key_row.get("quota_monthly_requests")
        if not isinstance(qd, int) or qd < 0:
            return _err("VALIDATION_ERROR", "API key quota_daily_requests is invalid.")
        if not isinstance(qm, int) or qm < 0:
            return _err("VALIDATION_ERROR", "API key quota_monthly_requests is invalid.")
        day_start = _dt_floor_day(now)
        month_start = _dt_floor_month(now)

        def _sum(period_type, period_start):
            ps_iso = period_start.isoformat() + "Z"
            s = 0
            for u in usage_rows:
                if not isinstance(u, dict):
                    continue
                if u.get("api_key_id") == api_key_id and u.get("period_type") == period_type and u.get("tool_name") == TOOL and u.get("period_start") == ps_iso:
                    rc = u.get("request_count")
                    if isinstance(rc, int) and rc >= 0:
                        s += rc
            return s

        used_day = _sum("day", day_start)
        used_month = _sum("month", month_start)
        if used_day + 1 > qd:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", quota_daily=qd, used_daily=used_day)
        if used_month + 1 > qm:
            return _err("QUOTA_EXCEEDED", "Monthly quota exceeded.", quota_monthly=qm, used_monthly=used_month)
        return None

    def _usage_increment(usage_rows, api_key_id, tool, cost_units):
        day_start = _dt_floor_day(now)
        month_start = _dt_floor_month(now)

        def _upsert(period_type, period_start):
            ps_iso = period_start.isoformat() + "Z"
            for u in usage_rows:
                if not isinstance(u, dict):
                    continue
                if u.get("api_key_id") == api_key_id and u.get("period_type") == period_type and u.get("tool_name") == tool and u.get("period_start") == ps_iso:
                    u["request_count"] = int(u.get("request_count") or 0) + 1
                    u["cost_units"] = int(u.get("cost_units") or 0) + int(cost_units)
                    u["last_request_at"] = now_iso
                    u["updated_at"] = now_iso
                    return
            usage_rows.append({
                "id": _new_id("uc"),
                "api_key_id": api_key_id,
                "period_type": period_type,
                "period_start": ps_iso,
                "tool_name": tool,
                "request_count": 1,
                "cost_units": int(cost_units),
                "last_request_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso
            })

        _upsert("day", day_start)
        _upsert("month", month_start)

    def _normalize_params(payload):
        norm = {}
        q = payload.get("query")
        if isinstance(q, str):
            norm["query"] = " ".join(q.strip().split())
        ct = payload.get("coord_type")
        if isinstance(ct, str) and ct.strip():
            norm["coord_type"] = ct.strip()
        if isinstance(payload.get("page"), int):
            norm["page"] = payload.get("page")
        if isinstance(payload.get("count"), int):
            norm["count"] = payload.get("count")
        return norm

    def _cache_key(norm_params):
        b = json.dumps({"tool": TOOL, "p": norm_params}, sort_keys=True, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    def _upstream_simulate(norm_params):
        # Deterministic fake geocode results. Respect page/count by slicing.
        q = norm_params.get("query") or ""
        seed = hashlib.sha256(q.encode("utf-8")).hexdigest()
        total = (int(seed[:2], 16) % 35) + 1  # 1..36
        # generate total items
        items = []
        for i in range(total):
            h = hashlib.sha256(f"{q}|{i}".encode("utf-8")).hexdigest()
            lng = (int(h[:8], 16) % 3600000) / 10000.0 - 180.0
            lat = (int(h[8:16], 16) % 1800000) / 10000.0 - 90.0
            items.append({
                "roadAddress": f"{q} Road {i}",
                "jibunAddress": f"{q} Jibun {i}",
                "englishAddress": f"{q} EN {i}",
                "addressElements": [],
                "x": f"{lng:.6f}",
                "y": f"{lat:.6f}",
                "distance": ""
            })
        page_v = norm_params.get("page") or 1
        count_v = norm_params.get("count") or min(10, total)
        start_idx = (page_v - 1) * count_v
        end_idx = start_idx + count_v
        slice_items = items[start_idx:end_idx] if start_idx < total else []
        return {
            "status": "OK",
            "meta": {
                "totalCount": total,
                "page": page_v,
                "count": count_v
            },
            "addresses": slice_items,
            "errorMessage": ""
        }

    # ---- Validate inputs ----
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query must be a non-empty string.")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided.")
    if coord_type is not None and not isinstance(coord_type, str):
        return _err("VALIDATION_ERROR", "coord_type must be a string when provided.")
    if page is not None:
        if not isinstance(page, int) or isinstance(page, bool) or page < 1 or page > 1000:
            return _err("VALIDATION_ERROR", "page must be an integer in range [1, 1000] when provided.")
    if count is not None:
        if not isinstance(count, int) or isinstance(count, bool) or count < 1 or count > 100:
            return _err("VALIDATION_ERROR", "count must be an integer in range [1, 100] when provided.")

    payload = {
        "api_key": api_key,
        "idempotency_key": idempotency_key,
        "query": query,
        "coord_type": coord_type,
        "page": page,
        "count": count
    }
    norm = _normalize_params(payload)
    cache_key = _cache_key(norm)

    # ---- Load store ----
    api_keys_rows = _load("api_keys.json")
    naver_creds_rows = _load("naver_credentials.json")
    map_requests_rows = _load("map_requests.json")
    map_responses_rows = _load("map_responses.json")
    usage_rows = _load("usage_counters.json")

    key_row = _authenticate_key(api_key, api_keys_rows)
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid API key.")
    api_key_id = key_row.get("id")

    # Idempotency replay
    if idempotency_key is not None:
        hit = _find_idempotent_success(map_requests_rows, map_responses_rows, api_key_id, TOOL, idempotency_key)
        if hit:
            req_row0, resp_row0 = hit
            cached_req_id = _new_id("mrq")
            cached_row = {
                "id": cached_req_id,
                "api_key_id": api_key_id,
                "naver_credential_id": None,
                "tool_name": TOOL,
                "idempotency_key": idempotency_key,
                "status": "cached",
                "cache_key": req_row0.get("cache_key"),
                "client_ip": None,
                "user_agent": None,
                "request_params": payload,
                "normalized_params": norm,
                "upstream_endpoint": None,
                "upstream_status_code": None,
                "upstream_error_code": None,
                "duration_ms": int((time.time() - t0) * 1000),
                "response_size_bytes": None,
                "cost_units": 0,
                "error_message": None,
                "created_at": now_iso,
                "updated_at": now_iso
            }
            map_requests_rows.append(cached_row)
            _save("map_requests.json", map_requests_rows)
            return {
                "request": cached_row,
                "cached_from_request_id": req_row0.get("id"),
                "response": resp_row0
            }

    # Create request row (received)
    req_id = _new_id("mrq")
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "naver_credential_id": None,
        "tool_name": TOOL,
        "idempotency_key": idempotency_key,
        "status": "received",
        "cache_key": cache_key,
        "client_ip": None,
        "user_agent": None,
        "request_params": payload,
        "normalized_params": norm,
        "upstream_endpoint": None,
        "upstream_status_code": None,
        "upstream_error_code": None,
        "duration_ms": None,
        "response_size_bytes": None,
        "cost_units": COST_UNITS_DEFAULT,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }

    if idempotency_key is not None:
        for r in map_requests_rows:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") == api_key_id and r.get("tool_name") == TOOL and r.get("idempotency_key") == idempotency_key:
                return _err("CONFLICT", "Duplicate idempotency_key for this tool and API key.", existing_request_id=r.get("id"), existing_status=r.get("status"))

    # Reject if key not active
    if key_row.get("status") != "active":
        req_row["status"] = "rejected"
        req_row["error_message"] = "API key is not active."
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        req_row["updated_at"] = now_iso
        map_requests_rows.append(req_row)
        _save("map_requests.json", map_requests_rows)
        return _err("UNAUTHORIZED", "API key is not active.", request=req_row)

    # Endpoint allowed
    allowed = key_row.get("allowed_endpoints")
    if not (isinstance(allowed, list) and TOOL in allowed):
        req_row["status"] = "rejected"
        req_row["error_message"] = "Endpoint not allowed for this API key."
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        req_row["updated_at"] = now_iso
        map_requests_rows.append(req_row)
        _save("map_requests.json", map_requests_rows)
        return _err("UNAUTHORIZED", "Endpoint not allowed for this API key.", request=req_row)

    # Rate limits and quotas
    rl_err = _rate_limit_check(map_requests_rows, api_key_id, key_row)
    if rl_err:
        req_row["status"] = "rejected"
        req_row["error_message"] = rl_err["error"]["message"]
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        req_row["updated_at"] = now_iso
        map_requests_rows.append(req_row)
        _save("map_requests.json", map_requests_rows)
        return rl_err

    q_err = _quota_check(usage_rows, api_key_id, key_row)
    if q_err:
        req_row["status"] = "rejected"
        req_row["error_message"] = q_err["error"]["message"]
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        req_row["updated_at"] = now_iso
        map_requests_rows.append(req_row)
        _save("map_requests.json", map_requests_rows)
        return q_err

    # Bill at accept-time
    _usage_increment(usage_rows, api_key_id, TOOL, req_row["cost_units"])

    cred = _pick_upstream_credential(naver_creds_rows)
    if cred is None:
        req_row["status"] = "failed"
        req_row["error_message"] = "No active upstream credential with required scope."
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        req_row["updated_at"] = now_iso
        map_requests_rows.append(req_row)
        _save("map_requests.json", map_requests_rows)
        _save("usage_counters.json", usage_rows)
        return _err("UNAUTHORIZED", "No upstream credential available for this operation.", request=req_row)

    # calling_upstream -> succeeded
    req_row["status"] = "calling_upstream"
    req_row["naver_credential_id"] = cred.get("id")
    req_row["upstream_endpoint"] = "/map-geocode/v2/geocode"
    req_row["updated_at"] = now_iso

    upstream_payload = _upstream_simulate(norm)
    req_row["upstream_status_code"] = 200
    req_row["status"] = "succeeded"
    req_row["updated_at"] = now_iso
    req_row["duration_ms"] = int((time.time() - t0) * 1000)
    resp_bytes = len(json.dumps(upstream_payload, ensure_ascii=False).encode("utf-8"))
    req_row["response_size_bytes"] = resp_bytes

    resp_row = {
        "id": _new_id("mrsp"),
        "request_id": req_id,
        "content_type": "application/json",
        "payload_json": upstream_payload,
        "payload_text": None,
        "image_data_uri": None,
        "blob_object_key": None,
        "sha256": hashlib.sha256(json.dumps(upstream_payload, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest(),
        "expires_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }

    map_requests_rows.append(req_row)
    map_responses_rows.append(resp_row)
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso

    _save("map_requests.json", map_requests_rows)
    _save("map_responses.json", map_responses_rows)
    _save("usage_counters.json", usage_rows)
    _save("api_keys.json", api_keys_rows)

    return {"request": req_row, "response": resp_row}

def naver_reverse_geocode(api_key, coords, idempotency_key=None, output=None, orders=None, coord_type=None, **_extra):
    import json, os, datetime, time, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0411000" if __import__("os").path.isdir("./environment_mix/0411000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    TOOL = "naver_reverse_geocode"
    REQUIRED_SCOPE = "reverse_geocode"
    COST_UNITS_DEFAULT = 1

    def _dt_floor_day(dt):
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)
    def _dt_floor_month(dt):
        return dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_lnglat(s):
        if not isinstance(s, str):
            return None
        parts = [p.strip() for p in s.split(",")]
        if len(parts) != 2:
            return None
        try:
            lng = float(parts[0]); lat = float(parts[1])
        except Exception:
            return None
        if not (-180.0 <= lng <= 180.0 and -90.0 <= lat <= 90.0):
            return None
        return {"lng": lng, "lat": lat}

    def _authenticate_key(api_key_value, api_keys_rows):
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        s = api_key_value.strip()
        for r in api_keys_rows:
            if not isinstance(r, dict):
                continue
            if r.get("id") == s or r.get("key_prefix") == s:
                return r
        if len(s) >= 8:
            pref = s[:8]
            for r in api_keys_rows:
                if isinstance(r, dict) and r.get("key_prefix") == pref:
                    return r
        return None

    def _pick_upstream_credential(naver_creds_rows):
        for c in naver_creds_rows:
            if not isinstance(c, dict):
                continue
            if c.get("provider") != "naver":
                continue
            if c.get("status") != "active":
                continue
            scopes = c.get("scopes")
            if isinstance(scopes, list) and REQUIRED_SCOPE in scopes:
                return c
        return None

    def _find_idempotent_success(map_requests_rows, map_responses_rows, api_key_id, tool, idem_key):
        if idem_key is None:
            return None
        for r in map_requests_rows:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") == api_key_id and r.get("tool_name") == tool and r.get("idempotency_key") == idem_key:
                if r.get("status") in ("succeeded", "cached"):
                    req_id = r.get("id")
                    for resp in map_responses_rows:
                        if isinstance(resp, dict) and resp.get("request_id") == req_id:
                            return (r, resp)
        return None

    def _rate_limit_check(map_requests_rows, api_key_id, key_row):
        try:
            rps = float(key_row.get("rate_limit_rps"))
        except Exception:
            return _err("VALIDATION_ERROR", "API key rate_limit_rps is invalid.")
        burst = key_row.get("rate_limit_burst")
        if not isinstance(burst, int) or burst < 0:
            return _err("VALIDATION_ERROR", "API key rate_limit_burst is invalid.")
        if rps <= 0:
            return _err("VALIDATION_ERROR", "API key rate_limit_rps must be > 0.")
        window_start = (now - datetime.timedelta(seconds=1))
        count = 0
        for r in map_requests_rows:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start:
                count += 1
        allowed = int(burst + rps * 1.0)
        if count >= allowed:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit_rps=rps, burst=burst)
        return None

    def _quota_check(usage_rows, api_key_id, key_row):
        qd = key_row.get("quota_daily_requests")
        qm = key_row.get("quota_monthly_requests")
        if not isinstance(qd, int) or qd < 0:
            return _err("VALIDATION_ERROR", "API key quota_daily_requests is invalid.")
        if not isinstance(qm, int) or qm < 0:
            return _err("VALIDATION_ERROR", "API key quota_monthly_requests is invalid.")
        day_start = _dt_floor_day(now)
        month_start = _dt_floor_month(now)

        def _sum(period_type, period_start):
            ps_iso = period_start.isoformat() + "Z"
            for u in usage_rows:
                if not isinstance(u, dict):
                    continue
                if u.get("api_key_id") == api_key_id and u.get("period_type") == period_type and u.get("tool_name") == TOOL and u.get("period_start") == ps_iso:
                    rc = u.get("request_count")
                    if isinstance(rc, int) and rc >= 0:
                        return rc
            return 0

        used_day = _sum("day", day_start)
        used_month = _sum("month", month_start)
        if used_day + 1 > qd:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", quota_daily=qd, used_daily=used_day)
        if used_month + 1 > qm:
            return _err("QUOTA_EXCEEDED", "Monthly quota exceeded.", quota_monthly=qm, used_monthly=used_month)
        return None

    def _usage_increment(usage_rows, api_key_id, tool, cost_units):
        day_start = _dt_floor_day(now)
        month_start = _dt_floor_month(now)

        def _upsert(period_type, period_start):
            ps_iso = period_start.isoformat() + "Z"
            for u in usage_rows:
                if not isinstance(u, dict):
                    continue
                if u.get("api_key_id") == api_key_id and u.get("period_type") == period_type and u.get("tool_name") == tool and u.get("period_start") == ps_iso:
                    u["request_count"] = int(u.get("request_count") or 0) + 1
                    u["cost_units"] = int(u.get("cost_units") or 0) + int(cost_units)
                    u["last_request_at"] = now_iso
                    u["updated_at"] = now_iso
                    return
            usage_rows.append({
                "id": _new_id("uc"),
                "api_key_id": api_key_id,
                "period_type": period_type,
                "period_start": ps_iso,
                "tool_name": tool,
                "request_count": 1,
                "cost_units": int(cost_units),
                "last_request_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso
            })

        _upsert("day", day_start)
        _upsert("month", month_start)

    def _normalize_params(payload):
        norm = {}
        pc = _parse_lnglat(payload.get("coords"))
        if pc:
            norm["coords"] = pc
        for k in ("output", "orders", "coord_type"):
            v = payload.get(k)
            if isinstance(v, str) and v.strip():
                norm[k] = v.strip()
        return norm

    def _cache_key(norm_params):
        b = json.dumps({"tool": TOOL, "p": norm_params}, sort_keys=True, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    def _upstream_simulate(norm_params):
        c = norm_params.get("coords") or {"lng": None, "lat": None}
        seed = hashlib.sha256(json.dumps(norm_params, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()
        # Fake structured result
        return {
            "status": {"code": 0, "name": "ok", "message": "OK"},
            "results": [{
                "name": "roadaddr",
                "code": {"id": "FAKE", "type": "FAKE"},
                "region": {
                    "area0": {"name": "Korea", "coords": {"center": c}},
                    "area1": {"name": f"Region{int(seed[:2],16)%50}", "coords": {"center": c}},
                    "area2": {"name": f"City{int(seed[2:4],16)%200}", "coords": {"center": c}},
                    "area3": {"name": f"District{int(seed[4:6],16)%500}", "coords": {"center": c}},
                    "area4": {"name": f"Block{int(seed[6:8],16)%1000}", "coords": {"center": c}}
                },
                "land": {
                    "type": "1",
                    "name": f"Land{int(seed[8:12],16)%10000}",
                    "number1": str(int(seed[12:16],16)%200),
                    "number2": str(int(seed[16:20],16)%200),
                    "coords": {"center": c},
                    "addition0": {"type": "building", "value": f"Bldg{int(seed[20:24],16)%9999}"}
                }
            }],
            "input": {"coords": f"{c.get('lng')},{c.get('lat')}"}
        }

    # ---- Validate inputs ----
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(coords, str) or not coords.strip():
        return _err("VALIDATION_ERROR", "coords must be a non-empty string of form 'lng,lat'.")
    if _parse_lnglat(coords) is None:
        return _err("VALIDATION_ERROR", "coords must be in 'lng,lat' with valid ranges.")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided.")
    for sname, sval in (("output", output), ("orders", orders), ("coord_type", coord_type)):
        if sval is not None and not isinstance(sval, str):
            return _err("VALIDATION_ERROR", f"{sname} must be a string when provided.")

    payload = {
        "api_key": api_key,
        "idempotency_key": idempotency_key,
        "coords": coords,
        "output": output,
        "orders": orders,
        "coord_type": coord_type
    }
    norm = _normalize_params(payload)
    cache_key = _cache_key(norm)

    # ---- Load store ----
    api_keys_rows = _load("api_keys.json")
    naver_creds_rows = _load("naver_credentials.json")
    map_requests_rows = _load("map_requests.json")
    map_responses_rows = _load("map_responses.json")
    usage_rows = _load("usage_counters.json")

    key_row = _authenticate_key(api_key, api_keys_rows)
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid API key.")
    api_key_id = key_row.get("id")

    # Idempotency replay
    if idempotency_key is not None:
        hit = _find_idempotent_success(map_requests_rows, map_responses_rows, api_key_id, TOOL, idempotency_key)
        if hit:
            req_row0, resp_row0 = hit
            cached_req_id = _new_id("mrq")
            cached_row = {
                "id": cached_req_id,
                "api_key_id": api_key_id,
                "naver_credential_id": None,
                "tool_name": TOOL,
                "idempotency_key": idempotency_key,
                "status": "cached",
                "cache_key": req_row0.get("cache_key"),
                "client_ip": None,
                "user_agent": None,
                "request_params": payload,
                "normalized_params": norm,
                "upstream_endpoint": None,
                "upstream_status_code": None,
                "upstream_error_code": None,
                "duration_ms": int((time.time() - t0) * 1000),
                "response_size_bytes": None,
                "cost_units": 0,
                "error_message": None,
                "created_at": now_iso,
                "updated_at": now_iso
            }
            map_requests_rows.append(cached_row)
            _save("map_requests.json", map_requests_rows)
            return {
                "request": cached_row,
                "cached_from_request_id": req_row0.get("id"),
                "response": resp_row0
            }

    # Create request row (received)
    req_id = _new_id("mrq")
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "naver_credential_id": None,
        "tool_name": TOOL,
        "idempotency_key": idempotency_key,
        "status": "received",
        "cache_key": cache_key,
        "client_ip": None,
        "user_agent": None,
        "request_params": payload,
        "normalized_params": norm,
        "upstream_endpoint": None,
        "upstream_status_code": None,
        "upstream_error_code": None,
        "duration_ms": None,
        "response_size_bytes": None,
        "cost_units": COST_UNITS_DEFAULT,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }

    if idempotency_key is not None:
        for r in map_requests_rows:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") == api_key_id and r.get("tool_name") == TOOL and r.get("idempotency_key") == idempotency_key:
                return _err("CONFLICT", "Duplicate idempotency_key for this tool and API key.", existing_request_id=r.get("id"), existing_status=r.get("status"))

    # Reject if key not active
    if key_row.get("status") != "active":
        req_row["status"] = "rejected"
        req_row["error_message"] = "API key is not active."
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        req_row["updated_at"] = now_iso
        map_requests_rows.append(req_row)
        _save("map_requests.json", map_requests_rows)
        return _err("UNAUTHORIZED", "API key is not active.", request=req_row)

    # Endpoint allowed
    allowed = key_row.get("allowed_endpoints")
    if not (isinstance(allowed, list) and TOOL in allowed):
        req_row["status"] = "rejected"
        req_row["error_message"] = "Endpoint not allowed for this API key."
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        req_row["updated_at"] = now_iso
        map_requests_rows.append(req_row)
        _save("map_requests.json", map_requests_rows)
        return _err("UNAUTHORIZED", "Endpoint not allowed for this API key.", request=req_row)

    # Rate limits and quotas
    rl_err = _rate_limit_check(map_requests_rows, api_key_id, key_row)
    if rl_err:
        req_row["status"] = "rejected"
        req_row["error_message"] = rl_err["error"]["message"]
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        req_row["updated_at"] = now_iso
        map_requests_rows.append(req_row)
        _save("map_requests.json", map_requests_rows)
        return rl_err

    q_err = _quota_check(usage_rows, api_key_id, key_row)
    if q_err:
        req_row["status"] = "rejected"
        req_row["error_message"] = q_err["error"]["message"]
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        req_row["updated_at"] = now_iso
        map_requests_rows.append(req_row)
        _save("map_requests.json", map_requests_rows)
        return q_err

    # Bill at accept-time
    _usage_increment(usage_rows, api_key_id, TOOL, req_row["cost_units"])

    cred = _pick_upstream_credential(naver_creds_rows)
    if cred is None:
        req_row["status"] = "failed"
        req_row["error_message"] = "No active upstream credential with required scope."
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        req_row["updated_at"] = now_iso
        map_requests_rows.append(req_row)
        _save("map_requests.json", map_requests_rows)
        _save("usage_counters.json", usage_rows)
        return _err("UNAUTHORIZED", "No upstream credential available for this operation.", request=req_row)

    req_row["status"] = "calling_upstream"
    req_row["naver_credential_id"] = cred.get("id")
    req_row["upstream_endpoint"] = "/map-reversegeocode/v2/gc"
    req_row["updated_at"] = now_iso

    upstream_payload = _upstream_simulate(norm)
    req_row["upstream_status_code"] = 200
    req_row["status"] = "succeeded"
    req_row["updated_at"] = now_iso
    req_row["duration_ms"] = int((time.time() - t0) * 1000)
    resp_bytes = len(json.dumps(upstream_payload, ensure_ascii=False).encode("utf-8"))
    req_row["response_size_bytes"] = resp_bytes

    resp_row = {
        "id": _new_id("mrsp"),
        "request_id": req_id,
        "content_type": "application/json",
        "payload_json": upstream_payload,
        "payload_text": None,
        "image_data_uri": None,
        "blob_object_key": None,
        "sha256": hashlib.sha256(json.dumps(upstream_payload, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest(),
        "expires_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }

    map_requests_rows.append(req_row)
    map_responses_rows.append(resp_row)
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso

    _save("map_requests.json", map_requests_rows)
    _save("map_responses.json", map_responses_rows)
    _save("usage_counters.json", usage_rows)
    _save("api_keys.json", api_keys_rows)

    return {"request": req_row, "response": resp_row}

def naver_static_map(api_key, idempotency_key=None, center=None, level=None, w=None, h=None, scale=None, format=None, maptype=None, markers=None, path=None, **_extra):
    import json, os, datetime, time, uuid, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0411000" if __import__("os").path.isdir("./environment_mix/0411000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    TOOL = "naver_static_map"
    REQUIRED_SCOPE = "static_map"
    UPSTREAM_ENDPOINT = "https://naveropenapi.apigw.ntruss.com/map-static/v2/raster"
    COST_UNITS_DEFAULT = 2  # static map is higher cost by policy

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _iso(dt):
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        # ULID-like not required; ensure uniqueness and keep service prefix convention
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_lnglat(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        parts = [p.strip() for p in s.split(",")]
        if len(parts) != 2:
            return None
        try:
            lng = float(parts[0])
            lat = float(parts[1])
        except Exception:
            return None
        if not (-180.0 <= lng <= 180.0 and -90.0 <= lat <= 90.0):
            return None
        return {"lng": lng, "lat": lat}

    def _dt_floor_day(dt):
        return dt.astimezone(datetime.timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0)

    def _dt_floor_month(dt):
        return dt.astimezone(datetime.timezone.utc).replace(day=1, hour=0, minute=0, second=0, microsecond=0)

    def _counter_row_id(api_key_id, period_type, period_start_iso, tool_name):
        raw = f"{api_key_id}|{period_type}|{period_start_iso}|{tool_name}"
        return "nmd_use_" + hashlib.sha256(raw.encode("utf-8")).hexdigest()[:26]

    def _compute_rate_state(request_rows, api_key_id, now_dt, rps, burst):
        # token bucket: capacity=burst, refill=rps tokens/sec. We reconstruct from recent logs.
        if rps <= 0:
            return False
        capacity = max(0.0, float(burst))
        tokens = capacity
        last_t = None
        # consider recent accepted/billable attempts; for rate limiting we consider all requests (including rejected due to rate?)
        # real systems count attempts; we'll count all requests for this api_key/tool in last 5 minutes.
        cutoff = now_dt - datetime.timedelta(minutes=5)
        events = []
        for r in request_rows:
            if r.get("api_key_id") != api_key_id:
                continue
            if r.get("tool_name") != TOOL:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt < cutoff:
                continue
            # Count every received request attempt for this endpoint
            events.append((dt, r.get("id")))
        events.sort(key=lambda x: x[0])
        for dt, _ in events:
            if last_t is None:
                last_t = dt
            else:
                delta = (dt - last_t).total_seconds()
                if delta > 0:
                    tokens = min(capacity, tokens + delta * float(rps))
                last_t = dt
            # one token spent per request attempt
            if tokens >= 1.0:
                tokens -= 1.0
            else:
                # at this point the historical stream already violated; treat as empty
                tokens = 0.0
        # now advance to current time
        if last_t is not None:
            delta = (now_dt - last_t).total_seconds()
            if delta > 0:
                tokens = min(capacity, tokens + delta * float(rps))
        else:
            tokens = capacity
        return tokens >= 1.0

    def _append_request(map_requests, req_row):
        map_requests.append(req_row)

    def _append_response(map_responses, res_row):
        map_responses.append(res_row)

    # --------- Load datastore ----------
    api_keys = _load("api_keys.json")
    naver_creds = _load("naver_credentials.json")
    map_requests = _load("map_requests.json")
    map_responses = _load("map_responses.json")
    usage_counters = _load("usage_counters.json")

    # --------- Validate inputs ----------
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided")
    if center is not None and _parse_lnglat(center) is None:
        return _err("VALIDATION_ERROR", "center must be 'lng,lat' with valid coordinate ranges")
    if level is not None and (not isinstance(level, int) or level < 0 or level > 20):
        return _err("VALIDATION_ERROR", "level must be an integer between 0 and 20")
    if w is not None and (not isinstance(w, int) or w <= 0 or w > 2000):
        return _err("VALIDATION_ERROR", "w must be an integer between 1 and 2000")
    if h is not None and (not isinstance(h, int) or h <= 0 or h > 2000):
        return _err("VALIDATION_ERROR", "h must be an integer between 1 and 2000")
    if scale is not None and (not isinstance(scale, int) or scale not in (1, 2)):
        return _err("VALIDATION_ERROR", "scale must be 1 or 2 when provided")
    if format is not None:
        if not isinstance(format, str):
            return _err("VALIDATION_ERROR", "format must be a string when provided")
        fmt = format.lower().strip()
        if fmt not in ("png", "jpeg", "jpg"):
            return _err("VALIDATION_ERROR", "format must be one of: png, jpeg, jpg")
    if maptype is not None and not isinstance(maptype, str):
        return _err("VALIDATION_ERROR", "maptype must be a string when provided")
    if markers is not None and not isinstance(markers, str):
        return _err("VALIDATION_ERROR", "markers must be a string when provided")
    if path is not None and not isinstance(path, str):
        return _err("VALIDATION_ERROR", "path must be a string when provided")

    # --------- Authenticate api key by id or prefix (never hash) ----------
    key_row = None
    # Accept full id match
    for k in api_keys if isinstance(api_keys, list) else []:
        if k.get("id") == api_key:
            key_row = k
            break
    # If not found, accept prefix match (client-visible) as fallback
    if key_row is None:
        for k in api_keys if isinstance(api_keys, list) else []:
            if k.get("key_prefix") == api_key:
                key_row = k
                break
    if key_row is None:
        # No request row can be created because we cannot reference a valid api_key_id
        return _err("UNAUTHORIZED", "invalid api_key")

    api_key_id = key_row.get("id")

    # --------- Idempotency: return first succeeded response for tuple ----------
    if idempotency_key is not None:
        existing_req = None
        for r in map_requests if isinstance(map_requests, list) else []:
            if r.get("api_key_id") == api_key_id and r.get("tool_name") == TOOL and r.get("idempotency_key") == idempotency_key:
                if r.get("status") in ("succeeded", "cached"):
                    existing_req = r
                    break
        if existing_req is not None:
            # find response (must exist for succeeded/cached)
            req_id = existing_req.get("id")
            existing_res = None
            for rr in map_responses if isinstance(map_responses, list) else []:
                if rr.get("request_id") == req_id:
                    existing_res = rr
                    break
            if existing_res is not None:
                # Log this invocation as a cached request row (exactly one row per invocation)
                # It must reference the api key and store request_params.
                req_row = {
                    "id": _new_id("nmd_req"),
                    "api_key_id": api_key_id,
                    "naver_credential_id": None,
                    "tool_name": TOOL,
                    "idempotency_key": idempotency_key,
                    "status": "cached",
                    "cache_key": None,
                    "client_ip": None,
                    "user_agent": None,
                    "request_params": {
                        "api_key": api_key,
                        "idempotency_key": idempotency_key,
                        "center": center,
                        "level": level,
                        "w": w,
                        "h": h,
                        "scale": scale,
                        "format": format,
                        "maptype": maptype,
                        "markers": markers,
                        "path": path,
                    },
                    "normalized_params": {"center": _parse_lnglat(center)} if center is not None else None,
                    "upstream_endpoint": None,
                    "upstream_status_code": None,
                    "upstream_error_code": None,
                    "duration_ms": int((time.time() - t0) * 1000),
                    "response_size_bytes": None,
                    "cost_units": 0,  # non-billable duplicate
                    "error_message": None,
                    "created_at": now_iso,
                    "updated_at": now_iso,
                }
                _append_request(map_requests, req_row)
                _save("map_requests.json", map_requests)

                # return the previously stored payload
                out = {
                    "request_id": req_row["id"],
                    "served_from_request_id": existing_req.get("id"),
                    "status": "cached",
                    "content_type": existing_res.get("content_type"),
                    "image_data_uri": existing_res.get("image_data_uri"),
                    "blob_object_key": existing_res.get("blob_object_key"),
                    "expires_at": existing_res.get("expires_at"),
                }
                return out
            # If existing_req succeeded but no response row exists, treat as data inconsistency: continue normally (create a new invocation)
            # This will still create a request row.

    # --------- Create the required map_requests row (exactly one per invocation) ----------
    req_id = _new_id("nmd_req")
    req_params = {
        "api_key": api_key,
        "idempotency_key": idempotency_key,
        "center": center,
        "level": level,
        "w": w,
        "h": h,
        "scale": scale,
        "format": format,
        "maptype": maptype,
        "markers": markers,
        "path": path,
    }
    norm = {"center": _parse_lnglat(center)} if center is not None else None

    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "naver_credential_id": None,
        "tool_name": TOOL,
        "idempotency_key": idempotency_key,
        "status": "received",
        "cache_key": None,
        "client_ip": None,
        "user_agent": None,
        "request_params": req_params,
        "normalized_params": norm,
        "upstream_endpoint": None,
        "upstream_status_code": None,
        "upstream_error_code": None,
        "duration_ms": None,
        "response_size_bytes": None,
        "cost_units": COST_UNITS_DEFAULT,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    _append_request(map_requests, req_row)

    # --------- Enforce API key status and endpoint permissions ----------
    if key_row.get("status") != "active":
        req_row["status"] = "rejected"
        req_row["error_message"] = "api_keys.status must be 'active' to accept requests"
        req_row["updated_at"] = now_iso
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        _save("map_requests.json", map_requests)
        return _err("UNAUTHORIZED", "api key is not active", request_id=req_id)

    allowed = key_row.get("allowed_endpoints")
    if not isinstance(allowed, list) or TOOL not in allowed:
        req_row["status"] = "rejected"
        req_row["error_message"] = "api key does not have permission for this endpoint"
        req_row["updated_at"] = now_iso
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        _save("map_requests.json", map_requests)
        return _err("UNAUTHORIZED", "api key not permitted for naver_static_map", request_id=req_id)

    # --------- Enforce rate limits (token bucket reconstructed from recent requests) ----------
    rps = key_row.get("rate_limit_rps")
    burst = key_row.get("rate_limit_burst")
    if not isinstance(rps, (int, float)) or rps <= 0:
        # schema requires > 0; treat as server config error but reject as validation
        req_row["status"] = "rejected"
        req_row["error_message"] = "api key rate_limit_rps misconfigured"
        req_row["updated_at"] = now_iso
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        _save("map_requests.json", map_requests)
        return _err("VALIDATION_ERROR", "api key rate limit misconfigured", request_id=req_id)
    if not isinstance(burst, int) or burst < 0:
        req_row["status"] = "rejected"
        req_row["error_message"] = "api key rate_limit_burst misconfigured"
        req_row["updated_at"] = now_iso
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        _save("map_requests.json", map_requests)
        return _err("VALIDATION_ERROR", "api key burst limit misconfigured", request_id=req_id)

    ok_rate = _compute_rate_state(map_requests, api_key_id, now, float(rps), int(burst))
    if not ok_rate:
        req_row["status"] = "rejected"
        req_row["error_message"] = "rate limit exceeded"
        req_row["updated_at"] = now_iso
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        _save("map_requests.json", map_requests)
        return _err("RATE_LIMIT", "rate limit exceeded", request_id=req_id)

    # --------- Enforce quotas using usage_counters (do not increment on reject) ----------
    day_start = _dt_floor_day(now)
    mon_start = _dt_floor_month(now)
    day_iso = _iso(day_start)
    mon_iso = _iso(mon_start)

    def _get_or_init_counter(period_type, period_iso):
        cid = _counter_row_id(api_key_id, period_type, period_iso, TOOL)
        for c in usage_counters if isinstance(usage_counters, list) else []:
            if c.get("id") == cid:
                return c
        c = {
            "id": cid,
            "api_key_id": api_key_id,
            "period_type": period_type,
            "period_start": period_iso,
            "tool_name": TOOL,
            "request_count": 0,
            "cost_units": 0,
            "last_request_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage_counters.append(c)
        return c

    day_counter = _get_or_init_counter("day", day_iso)
    mon_counter = _get_or_init_counter("month", mon_iso)

    qd = key_row.get("quota_daily_requests")
    qm = key_row.get("quota_monthly_requests")
    if not isinstance(qd, int) or qd < 0 or not isinstance(qm, int) or qm < 0:
        req_row["status"] = "rejected"
        req_row["error_message"] = "api key quotas misconfigured"
        req_row["updated_at"] = now_iso
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        _save("map_requests.json", map_requests)
        return _err("VALIDATION_ERROR", "api key quotas misconfigured", request_id=req_id)

    # request becomes billable at accept-time by policy
    if day_counter.get("request_count", 0) + 1 > qd:
        req_row["status"] = "rejected"
        req_row["error_message"] = "daily quota exceeded"
        req_row["updated_at"] = now_iso
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        _save("map_requests.json", map_requests)
        _save("usage_counters.json", usage_counters)
        return _err("QUOTA_EXCEEDED", "daily quota exceeded", request_id=req_id)
    if mon_counter.get("request_count", 0) + 1 > qm:
        req_row["status"] = "rejected"
        req_row["error_message"] = "monthly quota exceeded"
        req_row["updated_at"] = now_iso
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        _save("map_requests.json", map_requests)
        _save("usage_counters.json", usage_counters)
        return _err("QUOTA_EXCEEDED", "monthly quota exceeded", request_id=req_id)

    # --------- Transition to calling_upstream and select upstream credential with scope ----------
    # Must pick an active credential that has REQUIRED_SCOPE.
    chosen_cred = None
    for c in naver_creds if isinstance(naver_creds, list) else []:
        if c.get("provider") != "naver":
            continue
        if c.get("status") != "active":
            continue
        scopes = c.get("scopes")
        if not isinstance(scopes, list) or REQUIRED_SCOPE not in scopes:
            continue
        chosen_cred = c
        break
    if chosen_cred is None:
        req_row["status"] = "failed"
        req_row["error_message"] = "no active upstream credential available with required scope"
        req_row["updated_at"] = now_iso
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        _save("map_requests.json", map_requests)
        return _err("UNAUTHORIZED", "no active upstream credential for static_map", request_id=req_id)

    # Update key last_used_at on successful authentication
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso

    # Status transition: received -> calling_upstream
    req_row["status"] = "calling_upstream"
    req_row["naver_credential_id"] = chosen_cred.get("id")
    req_row["upstream_endpoint"] = UPSTREAM_ENDPOINT
    req_row["updated_at"] = now_iso

    # --------- Billable usage increment transactionally at accept-time ----------
    day_counter["request_count"] = int(day_counter.get("request_count", 0)) + 1
    day_counter["cost_units"] = int(day_counter.get("cost_units", 0)) + int(req_row["cost_units"])
    day_counter["last_request_at"] = now_iso
    day_counter["updated_at"] = now_iso

    mon_counter["request_count"] = int(mon_counter.get("request_count", 0)) + 1
    mon_counter["cost_units"] = int(mon_counter.get("cost_units", 0)) + int(req_row["cost_units"])
    mon_counter["last_request_at"] = now_iso
    mon_counter["updated_at"] = now_iso

    # Persist accept-time state changes before "calling upstream"
    _save("api_keys.json", api_keys)
    _save("usage_counters.json", usage_counters)
    _save("map_requests.json", map_requests)

    # --------- Simulate upstream call (offline): generate deterministic image payload ----------
    # Build a deterministic byte payload based on normalized params; not a real image, but stored as png/jpeg data URI.
    fmt = (format.lower().strip() if isinstance(format, str) and format else "png")
    if fmt == "jpg":
        fmt = "jpeg"
    content_type = "image/png" if fmt == "png" else "image/jpeg"
    upstream_status = 200

    # create deterministic bytes for dedup/integrity (but not a real image)
    payload_seed = json.dumps(
        {
            "tool": TOOL,
            "center": center,
            "level": level,
            "w": w,
            "h": h,
            "scale": scale,
            "maptype": maptype,
            "markers": markers,
            "path": path,
        },
        ensure_ascii=False,
        sort_keys=True,
    ).encode("utf-8")
    digest = hashlib.sha256(payload_seed).hexdigest()
    pseudo_bytes = ("NAVER_STATIC_MAP:" + digest).encode("utf-8")
    b64 = base64.b64encode(pseudo_bytes).decode("ascii")
    data_uri = f"data:{content_type};base64,{b64}"

    # --------- Store response (exactly one payload form) ----------
    res_id = _new_id("nmd_res")
    res_row = {
        "id": res_id,
        "request_id": req_id,
        "content_type": content_type,
        "payload_json": None,
        "payload_text": None,
        "image_data_uri": data_uri,
        "blob_object_key": None,
        "sha256": digest,
        "expires_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    _append_response(map_responses, res_row)

    # --------- Complete request lifecycle ----------
    req_row["status"] = "succeeded"
    req_row["upstream_status_code"] = upstream_status
    req_row["duration_ms"] = int((time.time() - t0) * 1000)
    req_row["response_size_bytes"] = len(data_uri.encode("utf-8"))
    req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))

    _save("map_responses.json", map_responses)
    _save("map_requests.json", map_requests)

    return {
        "request_id": req_id,
        "status": "succeeded",
        "content_type": content_type,
        "image_data_uri": data_uri,
        "sha256": digest,
        "expires_at": None,
    }

def naver_whoami(api_key, **_extra):
    import json, os, datetime, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0411000" if __import__("os").path.isdir("./environment_mix/0411000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat()

    # ---- helpers ----
    def _safe_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _day_start(dt):
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _month_start(dt):
        return dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)

    def _hash_prefix(v):
        # Deterministic, non-reversible representation for logging.
        h = hashlib.sha256(v.encode("utf-8")).hexdigest()
        return h[:8]

    def _new_id(prefix):
        # time-ordered id
        ts = int(now.timestamp() * 1000)
        rnd = os.urandom(6).hex()
        return f"{prefix}_{ts}_{rnd}"

    def _log_request(api_key_row, status, error_message=None, cost_units=0, naver_credential_id=None):
        reqs = _load("map_requests.json")
        rid = _new_id("mr")
        row = {
            "id": rid,
            "api_key_id": api_key_row["id"] if api_key_row else "unknown",
            "naver_credential_id": naver_credential_id,
            "tool_name": "naver_geocode",  # whoami isn't in tool_name enum; pick a stable existing tool for audit.
            "idempotency_key": None,
            "status": status,
            "cache_key": None,
            "client_ip": None,
            "user_agent": None,
            "request_params": {"endpoint": "naver_whoami"},
            "normalized_params": None,
            "upstream_endpoint": None,
            "upstream_status_code": None,
            "upstream_error_code": None,
            "duration_ms": None,
            "response_size_bytes": None,
            "cost_units": int(cost_units) if isinstance(cost_units, int) else 0,
            "error_message": error_message,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        reqs.append(row)
        _save("map_requests.json", reqs)
        return rid

    # ---- validate input ----
    if not isinstance(api_key, str) or not api_key.strip():
        # cannot log without a resolved key
        return _err("UNAUTHORIZED", "Missing or invalid api_key.")

    api_key = api_key.strip()

    api_keys = _load("api_keys.json")
    usage = _load("usage_counters.json")
    reqs = _load("map_requests.json")

    # Authenticate by matching client-visible value:
    # Prefer exact match to id; else match by key_prefix.
    key_row = None
    for r in api_keys:
        if isinstance(r, dict) and r.get("id") == api_key:
            key_row = r
            break
    if key_row is None:
        # Treat provided api_key as raw secret/prefix and match key_prefix.
        # We cannot validate against key_hash (no plaintext), per contract.
        for r in api_keys:
            if isinstance(r, dict) and r.get("key_prefix") == api_key:
                key_row = r
                break
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid api_key.")

    # Permission: key must allow calling this endpoint.
    # Map whoami to requiring at least one allowed endpoint, and specifically require naver_geocode capability.
    # (Vendor text: PERMISSION_DENIED; mapped to UNAUTHORIZED per available codes.)
    allowed = key_row.get("allowed_endpoints")
    if not isinstance(allowed, list) or "naver_geocode" not in allowed:
        _log_request(key_row, "rejected", error_message="Permission denied for endpoint.")
        return _err("UNAUTHORIZED", "Permission denied for this endpoint.")

    # Rate/quota snapshot should be available even if suspended/revoked
    # but tool itself should refuse? Vendor says whoami returns status; not necessarily deny.
    # We'll allow whoami for non-active keys but log it and do not increment usage.
    status = key_row.get("status")
    if status not in ("active", "suspended", "revoked"):
        _log_request(key_row, "failed", error_message="Key has invalid status in datastore.")
        return _err("CONFLICT", "API key is in an invalid state.")

    # Prepare usage snapshot
    day0 = _day_start(now)
    month0 = _month_start(now)
    day0_iso = day0.isoformat()
    month0_iso = month0.isoformat()

    def _usage_row(period_type, period_start_iso):
        for u in usage:
            if not isinstance(u, dict):
                continue
            if u.get("api_key_id") == key_row.get("id") and u.get("period_type") == period_type and u.get("period_start") == period_start_iso and u.get("tool_name") == "naver_geocode":
                return u
        return None

    day_u = _usage_row("day", day0_iso)
    month_u = _usage_row("month", month0_iso)
    day_count = int(day_u.get("request_count", 0)) if isinstance(day_u, dict) else 0
    month_count = int(month_u.get("request_count", 0)) if isinstance(month_u, dict) else 0

    # Rate-limit snapshot (approx): count requests in last 1 second window
    window_start = now - datetime.timedelta(seconds=1)
    rps_count = 0
    for rr in reqs:
        if not isinstance(rr, dict):
            continue
        if rr.get("api_key_id") != key_row.get("id"):
            continue
        c = _parse_dt(rr.get("created_at"))
        if c and c >= window_start:
            rps_count += 1

    # Log call
    _log_request(key_row, "succeeded" if status in ("active", "suspended", "revoked") else "failed")

    # Update last_used_at only on successful authentication; do not change if key is not active? rule says successful authentication.
    key_row2 = dict(key_row)
    key_row2["last_used_at"] = now_iso
    key_row2["updated_at"] = now_iso
    for i, r in enumerate(api_keys):
        if isinstance(r, dict) and r.get("id") == key_row2.get("id"):
            api_keys[i] = key_row2
            break
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "identity": {
            "api_key_id": key_row2.get("id"),
            "key_prefix": key_row2.get("key_prefix"),
            "owner_type": key_row2.get("owner_type"),
            "owner_id": key_row2.get("owner_id"),
            "name": key_row2.get("name"),
            "status": key_row2.get("status"),
            "allowed_endpoints": key_row2.get("allowed_endpoints"),
            "created_at": key_row2.get("created_at"),
            "updated_at": key_row2.get("updated_at"),
            "last_used_at": key_row2.get("last_used_at"),
        },
        "limits": {
            "quota_daily_requests": key_row2.get("quota_daily_requests"),
            "quota_monthly_requests": key_row2.get("quota_monthly_requests"),
            "rate_limit_rps": key_row2.get("rate_limit_rps"),
            "rate_limit_burst": key_row2.get("rate_limit_burst"),
        },
        "usage_snapshot": {
            "tool_name": "naver_geocode",
            "day": {
                "period_start": day0_iso,
                "request_count": day_count,
                "remaining": max(0, int(key_row2.get("quota_daily_requests", 0)) - day_count) if _safe_int(key_row2.get("quota_daily_requests")) else None,
            },
            "month": {
                "period_start": month0_iso,
                "request_count": month_count,
                "remaining": max(0, int(key_row2.get("quota_monthly_requests", 0)) - month_count) if _safe_int(key_row2.get("quota_monthly_requests")) else None,
            },
            "rate_limit": {
                "approx_rps_last_1s": rps_count,
                "rate_limit_rps": key_row2.get("rate_limit_rps"),
                "rate_limit_burst": key_row2.get("rate_limit_burst"),
            },
        },
        "meta": {"latency_ms": latency_ms},
    }

def api_keys_list(api_key, owner_type=None, owner_id=None, status=None, allowed_endpoint=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0411000" if __import__("os").path.isdir("./environment_mix/0411000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat()

    def _parse_dt(s):
        if s is None or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        ts = int(now.timestamp() * 1000)
        rnd = os.urandom(6).hex()
        return f"{prefix}_{ts}_{rnd}"

    def _log_request(api_key_row, status_value, error_message=None):
        reqs = _load("map_requests.json")
        rid = _new_id("mr")
        reqs.append({
            "id": rid,
            "api_key_id": api_key_row["id"] if api_key_row else "unknown",
            "naver_credential_id": None,
            "tool_name": "naver_geocode",  # audit surrogate
            "idempotency_key": None,
            "status": status_value,
            "cache_key": None,
            "client_ip": None,
            "user_agent": None,
            "request_params": {"endpoint": "api_keys_list"},
            "normalized_params": None,
            "upstream_endpoint": None,
            "upstream_status_code": None,
            "upstream_error_code": None,
            "duration_ms": None,
            "response_size_bytes": None,
            "cost_units": 0,
            "error_message": error_message,
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("map_requests.json", reqs)

    # ---- validate inputs ----
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "Missing or invalid api_key.")
    api_key = api_key.strip()

    if owner_type is not None:
        if not isinstance(owner_type, str) or owner_type not in ("user", "team", "service"):
            return _err("VALIDATION_ERROR", "Invalid owner_type.")
    if owner_id is not None and (not isinstance(owner_id, str) or not owner_id.strip()):
        return _err("VALIDATION_ERROR", "Invalid owner_id.")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "suspended", "revoked"):
            return _err("VALIDATION_ERROR", "Invalid status.")
    if allowed_endpoint is not None:
        if not isinstance(allowed_endpoint, str) or allowed_endpoint not in ("naver_directions", "naver_geocode", "naver_reverse_geocode", "naver_static_map"):
            return _err("VALIDATION_ERROR", "Invalid allowed_endpoint.")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "Invalid page_size.")
    if page_token is not None and (not isinstance(page_token, str) or not page_token.strip()):
        return _err("VALIDATION_ERROR", "Invalid page_token.")

    api_keys = _load("api_keys.json")

    # authenticate
    caller = None
    for r in api_keys:
        if isinstance(r, dict) and r.get("id") == api_key:
            caller = r
            break
    if caller is None:
        for r in api_keys:
            if isinstance(r, dict) and r.get("key_prefix") == api_key:
                caller = r
                break
    if caller is None:
        return _err("UNAUTHORIZED", "Invalid api_key.")

    # permission: must have naver_geocode in allowed_endpoints to enumerate (mapped PERMISSION_DENIED->UNAUTHORIZED)
    if not isinstance(caller.get("allowed_endpoints"), list) or "naver_geocode" not in caller.get("allowed_endpoints"):
        _log_request(caller, "rejected", error_message="Permission denied for endpoint.")
        return _err("UNAUTHORIZED", "Permission denied for this endpoint.")

    # scope: only keys belonging to same owner as caller (simple visibility model)
    caller_owner_type = caller.get("owner_type")
    caller_owner_id = caller.get("owner_id")

    # normalize filter owner_type: schema uses user/service/workspace, tool uses user/team/service
    def _match_owner_type(row_owner_type, filter_owner_type):
        if filter_owner_type is None:
            return True
        # map tool 'team' -> schema 'workspace'
        if filter_owner_type == "team":
            return row_owner_type == "workspace"
        return row_owner_type == filter_owner_type

    def _caller_can_see(row):
        return row.get("owner_type") == caller_owner_type and row.get("owner_id") == caller_owner_id

    # pagination token decode: base64 of json {"created_at": "...", "id": "..."}
    cursor_created = None
    cursor_id = None
    if page_token:
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"=" * (-len(page_token) % 4)).decode("utf-8")
            obj = json.loads(raw)
            cursor_created = obj.get("created_at")
            cursor_id = obj.get("id")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid page_token.")

    # filter
    rows = []
    for r in api_keys:
        if not isinstance(r, dict):
            continue
        if not _caller_can_see(r):
            continue
        if owner_type is not None:
            if not _match_owner_type(r.get("owner_type"), owner_type):
                continue
        if owner_id is not None and r.get("owner_id") != owner_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if allowed_endpoint is not None:
            a = r.get("allowed_endpoints")
            if not isinstance(a, list) or allowed_endpoint not in a:
                continue
        rows.append(r)

    # sort by created_at desc, tiebreaker by id desc
    def _sort_key(r):
        dt = _parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (dt, str(r.get("id") or ""))

    rows.sort(key=_sort_key, reverse=True)

    # apply cursor (start after cursor)
    if cursor_created and cursor_id:
        filtered = []
        cursor_dt = _parse_dt(cursor_created) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        for r in rows:
            rdt = _parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            rid = str(r.get("id") or "")
            if (rdt, rid) < (cursor_dt, str(cursor_id)):
                filtered.append(r)
        rows = filtered

    total = len(rows)
    page = rows[:page_size]
    has_more = total > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = json.dumps({"created_at": last.get("created_at"), "id": last.get("id")}, ensure_ascii=False)
        next_cursor = base64.urlsafe_b64encode(payload.encode("utf-8")).decode("utf-8").rstrip("=")

    _log_request(caller, "succeeded")

    latency_ms = int((time.time() - t0) * 1000)
    # Do not expose key_hash; only metadata
    def _public(r):
        return {
            "id": r.get("id"),
            "key_prefix": r.get("key_prefix"),
            "owner_type": r.get("owner_type"),
            "owner_id": r.get("owner_id"),
            "name": r.get("name"),
            "status": r.get("status"),
            "quota_daily_requests": r.get("quota_daily_requests"),
            "quota_monthly_requests": r.get("quota_monthly_requests"),
            "rate_limit_rps": r.get("rate_limit_rps"),
            "rate_limit_burst": r.get("rate_limit_burst"),
            "allowed_endpoints": r.get("allowed_endpoints"),
            "last_used_at": r.get("last_used_at"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
            "revoked_at": r.get("revoked_at"),
        }

    return {
        "api_keys": [_public(r) for r in page],
        "page": {
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_page_token": next_cursor,
        },
        "meta": {"latency_ms": latency_ms},
    }

def api_keys_create(api_key, owner_type, owner_id, name, allowed_endpoints, status=None, quota_daily_requests=None, quota_monthly_requests=None, rate_limit_rps=None, rate_limit_burst=None, **_extra):
    import json, os, datetime, time, uuid, secrets, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0411000" if __import__("os").path.isdir("./environment_mix/0411000") else "/app/database")
    def _load(n):
