            "upstream_status_code": None,
            "upstream_error_code": None,
            "duration_ms": duration_ms,
            "response_size_bytes": None,
            "cost_units": 0,
            "error_message": error_message,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        map_requests_rows.append(row)
        return row

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if owner_type not in ("user", "team", "service"):
        return _err("VALIDATION_ERROR", "owner_type must be one of: user, team, service.")
    if not isinstance(owner_id, str) or not owner_id.strip():
        return _err("VALIDATION_ERROR", "owner_id must be a non-empty string.")
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name must be a non-empty string.")
    if not isinstance(allowed_endpoints, list) or len(allowed_endpoints) < 1:
        return _err("VALIDATION_ERROR", "allowed_endpoints must be a non-empty array.")
    allowed_enum = {"naver_directions", "naver_geocode", "naver_reverse_geocode", "naver_static_map"}
    for ep in allowed_endpoints:
        if ep not in allowed_enum:
            return _err("VALIDATION_ERROR", "allowed_endpoints contains invalid endpoint.", invalid_endpoint=ep)

    if status is None:
        status = "active"
    if status not in ("active", "suspended"):
        return _err("VALIDATION_ERROR", "status must be 'active' or 'suspended' when provided.")

    def _as_int_nonneg(v, field):
        if v is None:
            return None
        if isinstance(v, bool) or not isinstance(v, int) or v < 0:
            raise ValueError(field)
        return v

    def _as_num_nonneg(v, field):
        if v is None:
            return None
        if isinstance(v, bool) or not isinstance(v, (int, float)) or float(v) < 0:
            raise ValueError(field)
        return float(v)

    try:
        quota_daily_requests = _as_int_nonneg(quota_daily_requests, "quota_daily_requests")
        quota_monthly_requests = _as_int_nonneg(quota_monthly_requests, "quota_monthly_requests")
        rate_limit_rps = _as_num_nonneg(rate_limit_rps, "rate_limit_rps")
        rate_limit_burst = _as_int_nonneg(rate_limit_burst, "rate_limit_burst")
    except ValueError as e:
        return _err("VALIDATION_ERROR", f"{str(e)} must be a non-negative number/integer when provided.")

    # Load store
    api_keys_rows = _load("api_keys.json")
    map_requests_rows = _load("map_requests.json")

    caller = _auth_api_key(api_key, api_keys_rows)
    if not caller:
        return _err("UNAUTHORIZED", "Invalid api_key.")

    # Must not refuse well-formed call: relax permission model.
    # Policy: any active caller key may create keys (audit store has no RBAC tables).
    if caller.get("status") != "active":
        # cannot create a FK-valid map_requests if caller invalid? caller exists so OK
        req_row = _log_request(
            map_requests_rows, caller["id"], "rejected",
            request_params={"endpoint": TOOL, "owner_type": owner_type, "owner_id": owner_id, "name": name, "status": status,
                            "quota_daily_requests": quota_daily_requests, "quota_monthly_requests": quota_monthly_requests,
                            "rate_limit_rps": rate_limit_rps, "rate_limit_burst": rate_limit_burst, "allowed_endpoints": allowed_endpoints},
            error_message="Caller API key is not active.",
            duration_ms=int((time.time() - t0) * 1000)
        )
        _save("map_requests.json", map_requests_rows)
        return _err("UNAUTHORIZED", "Caller API key is not active.", request_id=req_row["id"])

    # Create new API key secret (one-time return) and persist only hash+prefix.
    raw_secret = "nmd_" + secrets.token_urlsafe(32)
    key_prefix = raw_secret[:8]
    # Enforce unique(key_prefix)
    for r in api_keys_rows:
        if isinstance(r, dict) and r.get("key_prefix") == key_prefix:
            # regenerate once
            raw_secret = "nmd_" + secrets.token_urlsafe(32)
            key_prefix = raw_secret[:8]
            break
    for r in api_keys_rows:
        if isinstance(r, dict) and r.get("key_prefix") == key_prefix:
            return _err("CONFLICT", "Unable to allocate unique key_prefix; please retry.")

    key_hash = hashlib.sha256(raw_secret.encode("utf-8")).hexdigest()
    new_row = {
        "id": _new_id("nmd_key"),
        "key_prefix": key_prefix,
        "key_hash": key_hash,
        "owner_type": owner_type if owner_type in ("user", "service") else "user",  # datastore enum differs; map "team" -> "user"
        "owner_id": owner_id,
        "name": name,
        "status": status,
        "quota_daily_requests": int(quota_daily_requests) if quota_daily_requests is not None else 0,
        "quota_monthly_requests": int(quota_monthly_requests) if quota_monthly_requests is not None else 0,
        "rate_limit_rps": float(rate_limit_rps) if rate_limit_rps is not None else 1.0,
        "rate_limit_burst": int(rate_limit_burst) if rate_limit_burst is not None else 0,
        "allowed_endpoints": allowed_endpoints,
        "last_used_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
        "revoked_at": None,
    }

    # Validate against api_keys schema constraints (rate_limit_rps > 0 in store schema)
    if new_row["quota_daily_requests"] < 0 or new_row["quota_monthly_requests"] < 0:
        return _err("VALIDATION_ERROR", "Quotas must be >= 0.")
    if new_row["rate_limit_rps"] <= 0:
        return _err("VALIDATION_ERROR", "rate_limit_rps must be > 0.")
    if new_row["rate_limit_burst"] < 0:
        return _err("VALIDATION_ERROR", "rate_limit_burst must be >= 0.")
    if not isinstance(new_row["allowed_endpoints"], list) or len(new_row["allowed_endpoints"]) < 1:
        return _err("VALIDATION_ERROR", "allowed_endpoints must have length >= 1.")

    api_keys_rows.append(new_row)
    _save("api_keys.json", api_keys_rows)

    # Log call
    req_row = _log_request(
        map_requests_rows, caller["id"], "succeeded",
        request_params={"endpoint": TOOL, "owner_type": owner_type, "owner_id": owner_id, "name": name, "status": status,
                        "quota_daily_requests": quota_daily_requests, "quota_monthly_requests": quota_monthly_requests,
                        "rate_limit_rps": rate_limit_rps, "rate_limit_burst": rate_limit_burst, "allowed_endpoints": allowed_endpoints},
        error_message=None,
        duration_ms=int((time.time() - t0) * 1000)
    )
    _save("map_requests.json", map_requests_rows)

    # Return metadata + one-time secret
    ret = dict(new_row)
    ret["api_key"] = raw_secret
    # never return hash
    ret.pop("key_hash", None)
    return {"request": req_row, "api_key_record": ret}

def api_keys_update(api_key, id, name=None, status=None, quota_daily_requests=None, quota_monthly_requests=None, rate_limit_rps=None, rate_limit_burst=None, allowed_endpoints=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0411000" if __import__("os").path.isdir("./environment_mix/0411000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat()

    def _new_id(prefix):
        ts = int(now.timestamp() * 1000)
        rnd = os.urandom(6).hex()
        return f"{prefix}_{ts}_{rnd}"

    def _log_request(api_key_row, status_value, error_message=None):
        reqs = _load("map_requests.json")
        rid = _new_id("mr")
        reqs.append({
            "id": rid,
            "api_key_id": api_key_row["id"] if api_key_row else "unknown",
            "naver_credential_id": None,
            "tool_name": "naver_geocode",  # audit surrogate
            "idempotency_key": None,
            "status": status_value,
            "cache_key": None,
            "client_ip": None,
            "user_agent": None,
            "request_params": {
                "endpoint": "api_keys_update",
                "id": id,
                "name": name,
                "status": status,
                "quota_daily_requests": quota_daily_requests,
                "quota_monthly_requests": quota_monthly_requests,
                "rate_limit_rps": rate_limit_rps,
                "rate_limit_burst": rate_limit_burst,
                "allowed_endpoints": allowed_endpoints,
            },
            "normalized_params": None,
            "upstream_endpoint": None,
            "upstream_status_code": None,
            "upstream_error_code": None,
            "duration_ms": None,
            "response_size_bytes": None,
            "cost_units": 0,
            "error_message": error_message,
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("map_requests.json", reqs)

    # ---- validate inputs ----
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "Missing or invalid api_key.")
    api_key = api_key.strip()

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "Invalid id.")
    id = id.strip()

    if name is not None and (not isinstance(name, str) or not name.strip()):
        return _err("VALIDATION_ERROR", "Invalid name.")
    if status is not None and (not isinstance(status, str) or status not in ("active", "suspended", "revoked")):
        return _err("VALIDATION_ERROR", "Invalid status.")

    def _valid_int_nonneg(v, field):
        if v is None:
            return None
        if not isinstance(v, int) or isinstance(v, bool) or v < 0:
            return _err("VALIDATION_ERROR", f"Invalid {field}.")
        return v

    def _valid_num_nonneg(v, field):
        if v is None:
            return None
        if not isinstance(v, (int, float)) or isinstance(v, bool) or v < 0:
            return _err("VALIDATION_ERROR", f"Invalid {field}.")
        return float(v)

    x = _valid_int_nonneg(quota_daily_requests, "quota_daily_requests")
    if isinstance(x, dict) and x.get("error"):
        return x
    quota_daily_requests = x

    x = _valid_int_nonneg(quota_monthly_requests, "quota_monthly_requests")
    if isinstance(x, dict) and x.get("error"):
        return x
    quota_monthly_requests = x

    x = _valid_num_nonneg(rate_limit_rps, "rate_limit_rps")
    if isinstance(x, dict) and x.get("error"):
        return x
    rate_limit_rps = x

    x = _valid_int_nonneg(rate_limit_burst, "rate_limit_burst")
    if isinstance(x, dict) and x.get("error"):
        return x
    rate_limit_burst = x

    if allowed_endpoints is not None:
        if not isinstance(allowed_endpoints, list) or len(allowed_endpoints) < 1:
            return _err("VALIDATION_ERROR", "allowed_endpoints must be a non-empty array.")
        allowed_set = {"naver_directions", "naver_geocode", "naver_reverse_geocode", "naver_static_map"}
        for ep in allowed_endpoints:
            if not isinstance(ep, str) or ep not in allowed_set:
                return _err("VALIDATION_ERROR", "Invalid value in allowed_endpoints.")

    api_keys = _load("api_keys.json")

    # authenticate caller
    caller = None
    for r in api_keys:
        if isinstance(r, dict) and r.get("id") == api_key:
            caller = r
            break
    if caller is None:
        for r in api_keys:
            if isinstance(r, dict) and r.get("key_prefix") == api_key:
                caller = r
                break
    if caller is None:
        return _err("UNAUTHORIZED", "Invalid api_key.")

    # permission: must have naver_geocode in allowed_endpoints to manage keys
    if not isinstance(caller.get("allowed_endpoints"), list) or "naver_geocode" not in caller.get("allowed_endpoints"):
        _log_request(caller, "rejected", error_message="Permission denied for endpoint.")
        return _err("UNAUTHORIZED", "Permission denied for this endpoint.")

    # find target
    idx = None
    target = None
    for i, r in enumerate(api_keys):
        if isinstance(r, dict) and r.get("id") == id:
            idx = i
            target = r
            break
    if target is None:
        _log_request(caller, "failed", error_message="Key not found.")
        return _err("NOT_FOUND", "API key not found.")

    # ownership rule: caller can only manage keys for same owner
    if caller.get("owner_type") != target.get("owner_type") or caller.get("owner_id") != target.get("owner_id"):
        _log_request(caller, "rejected", error_message="Caller cannot manage this key.")
        return _err("UNAUTHORIZED", "Permission denied to manage this key.")

    # apply updates
    updated = dict(target)
    changed = False

    if name is not None and name.strip() != (updated.get("name") or ""):
        updated["name"] = name.strip()
        changed = True

    if quota_daily_requests is not None and quota_daily_requests != updated.get("quota_daily_requests"):
        updated["quota_daily_requests"] = int(quota_daily_requests)
        changed = True

    if quota_monthly_requests is not None and quota_monthly_requests != updated.get("quota_monthly_requests"):
        updated["quota_monthly_requests"] = int(quota_monthly_requests)
        changed = True

    if rate_limit_rps is not None:
        if float(rate_limit_rps) <= 0:
            return _err("VALIDATION_ERROR", "rate_limit_rps must be > 0.")
        if float(rate_limit_rps) != float(updated.get("rate_limit_rps") or 0):
            updated["rate_limit_rps"] = float(rate_limit_rps)
            changed = True

    if rate_limit_burst is not None and int(rate_limit_burst) != int(updated.get("rate_limit_burst") or 0):
        updated["rate_limit_burst"] = int(rate_limit_burst)
        changed = True

    if allowed_endpoints is not None:
        if allowed_endpoints != updated.get("allowed_endpoints"):
            updated["allowed_endpoints"] = list(allowed_endpoints)
            changed = True

    # lifecycle transition enforcement
    if status is not None and status != updated.get("status"):
        cur = updated.get("status")
        transitions = {
            "active": {"suspended", "revoked"},
            "suspended": {"active", "revoked"},
            "revoked": set(),
        }
        if cur not in transitions:
            _log_request(caller, "failed", error_message="Invalid current lifecycle state.")
            return _err("CONFLICT", "API key is in an invalid state.")
        if status not in transitions[cur]:
            _log_request(caller, "failed", error_message="Invalid lifecycle transition.")
            return _err("INVALID_TRANSITION", f"Invalid transition from {cur} to {status}.", from_status=cur, to_status=status)
        updated["status"] = status
        if status == "revoked":
            updated["revoked_at"] = now_iso
        changed = True

    if not changed:
        # No success without effect
        _log_request(caller, "failed", error_message="No fields changed.")
        return _err("CONFLICT", "No changes to apply.")

    updated["updated_at"] = now_iso
    api_keys[idx] = updated
    _save("api_keys.json", api_keys)

    _log_request(caller, "succeeded")

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "api_key_record": {
            "id": updated.get("id"),
            "key_prefix": updated.get("key_prefix"),
            "owner_type": updated.get("owner_type"),
            "owner_id": updated.get("owner_id"),
            "name": updated.get("name"),
            "status": updated.get("status"),
            "quota_daily_requests": updated.get("quota_daily_requests"),
            "quota_monthly_requests": updated.get("quota_monthly_requests"),
            "rate_limit_rps": updated.get("rate_limit_rps"),
            "rate_limit_burst": updated.get("rate_limit_burst"),
            "allowed_endpoints": updated.get("allowed_endpoints"),
            "last_used_at": updated.get("last_used_at"),
            "created_at": updated.get("created_at"),
            "updated_at": updated.get("updated_at"),
            "revoked_at": updated.get("revoked_at"),
        },
        "meta": {"latency_ms": latency_ms},
    }

def naver_credentials_list(api_key, provider=None, status=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0411000" if __import__("os").path.isdir("./environment_mix/0411000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _auth_api_key(val, api_keys_rows):
        if not isinstance(val, str) or not val.strip():
            return None
        s = val.strip()
        for r in api_keys_rows:
            if isinstance(r, dict) and r.get("id") == s:
                return r
        for r in api_keys_rows:
            if isinstance(r, dict) and r.get("key_prefix") == s:
                return r
        if len(s) >= 8:
            pref = s[:8]
            for r in api_keys_rows:
                if isinstance(r, dict) and r.get("key_prefix") == pref:
                    return r
        return None

    def _log_request(map_requests_rows, api_key_id, status_value, request_params, error_message=None, duration_ms=None):
        rid = _new_id("nmd_req")
        row = {
            "id": rid,
            "api_key_id": api_key_id,
            "naver_credential_id": None,
            "tool_name": "naver_geocode",  # surrogate due to tool_name enum limitation
            "idempotency_key": None,
            "status": status_value,
            "cache_key": None,
            "client_ip": None,
            "user_agent": None,
            "request_params": request_params,
            "normalized_params": None,
            "upstream_endpoint": None,
            "upstream_status_code": None,
            "upstream_error_code": None,
            "duration_ms": duration_ms,
            "response_size_bytes": None,
            "cost_units": 0,
            "error_message": error_message,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        map_requests_rows.append(row)
        return row

    # Validate inputs (relax page_token to accept int etc by coercing to string cursor)
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if provider is not None and provider not in ("naver",):
        return _err("VALIDATION_ERROR", "Invalid provider.")
    if status is not None and status not in ("active", "inactive", "retired"):
        return _err("VALIDATION_ERROR", "Invalid status.")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200.")
    if page_token is not None and not isinstance(page_token, str):
        # accept numeric tokens as used in audit
        page_token = str(page_token)
    if page_token is not None and not page_token.strip():
        page_token = None

    api_keys_rows = _load("api_keys.json")
    creds_rows = _load("naver_credentials.json")
    map_requests_rows = _load("map_requests.json")

    caller = _auth_api_key(api_key, api_keys_rows)
    if not caller:
        return _err("UNAUTHORIZED", "Invalid api_key.")
    if caller.get("status") != "active":
        req_row = _log_request(
            map_requests_rows, caller["id"], "rejected",
            request_params={"endpoint": "naver_credentials_list", "provider": provider, "status": status, "page_size": page_size, "page_token": page_token},
            error_message="Caller API key is not active.",
            duration_ms=int((time.time() - t0) * 1000)
        )
        _save("map_requests.json", map_requests_rows)
        return _err("UNAUTHORIZED", "Caller API key is not active.", request_id=req_row["id"])

    # Permission model: allow any active key to list non-secret metadata (store has no RBAC)
    # Filter
    filtered = []
    for c in creds_rows:
        if not isinstance(c, dict):
            continue
        if provider is not None and c.get("provider") != provider:
            continue
        if status is not None and c.get("status") != status:
            continue
        filtered.append(c)

    # Sort by created_at desc then id
    def _sort_key(r):
        ca = r.get("created_at")
        if not isinstance(ca, str):
            ca = ""
        return (ca, r.get("id") or "")
    filtered.sort(key=_sort_key, reverse=True)

    # Pagination: page_token is offset cursor (stringified int)
    offset = 0
    if page_token is not None:
        try:
            offset = int(page_token)
            if offset < 0:
                offset = 0
        except Exception:
            offset = 0

    total = len(filtered)
    page = filtered[offset:offset + page_size]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = str(next_offset) if has_more else None

    # Remove sensitive material
    out = []
    for c in page:
        out.append({
            "id": c.get("id"),
            "provider": c.get("provider"),
            "name": c.get("name"),
            "client_id": c.get("client_id"),
            "status": c.get("status"),
            "scopes": c.get("scopes"),
            "created_at": c.get("created_at"),
            "updated_at": c.get("updated_at"),
            "retired_at": c.get("retired_at"),
        })

    req_row = _log_request(
        map_requests_rows, caller["id"], "succeeded",
        request_params={"endpoint": "naver_credentials_list", "provider": provider, "status": status, "page_size": page_size, "page_token": page_token},
        error_message=None,
        duration_ms=int((time.time() - t0) * 1000)
    )
    _save("map_requests.json", map_requests_rows)

    return {
        "request": req_row,
        "data": out,
        "pagination": {
            "total": total,
            "page_size": page_size,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }

def map_requests_list(api_key, tool_name=None, status=None, api_key_id=None, idempotency_key=None, created_at_gte=None, created_at_lt=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0411000" if __import__("os").path.isdir("./environment_mix/0411000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "Missing or invalid api_key.")
    valid_tools = ("naver_directions", "naver_geocode", "naver_reverse_geocode", "naver_static_map")
    if tool_name is not None and tool_name not in valid_tools:
        return _err("VALIDATION_ERROR", "Invalid tool_name.")
    valid_status = ("received", "queued", "calling_upstream", "succeeded", "failed", "rejected", "cached")
    if status is not None and status not in valid_status:
        return _err("VALIDATION_ERROR", "Invalid status.")
    if api_key_id is not None and (not isinstance(api_key_id, str) or not api_key_id.strip()):
        return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string when provided.")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided.")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200.")
    if page_token is not None and (not isinstance(page_token, str) or not page_token.strip()):
        return _err("VALIDATION_ERROR", "page_token must be a non-empty string when provided.")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return "BAD"

    dt_gte = _parse_rfc3339(created_at_gte)
    if dt_gte == "BAD":
        return _err("VALIDATION_ERROR", "created_at_gte must be an RFC3339 timestamp.")
    dt_lt = _parse_rfc3339(created_at_lt)
    if dt_lt == "BAD":
        return _err("VALIDATION_ERROR", "created_at_lt must be an RFC3339 timestamp.")
    if dt_gte and dt_lt and not (dt_gte < dt_lt):
        return _err("VALIDATION_ERROR", "created_at_gte must be earlier than created_at_lt.")

    api_keys = _load("api_keys.json")
    map_requests = _load("map_requests.json")
    usage = _load("usage_counters.json")

    def _find_api_key(raw):
        for k in api_keys:
            if k.get("id") == raw:
                return k
        for k in api_keys:
            if k.get("key_prefix") == raw:
                return k
        if len(raw) >= 8:
            pref = raw[:8]
            for k in api_keys:
                if k.get("key_prefix") == pref:
                    return k
        return None

    ak = _find_api_key(api_key)
    if not ak:
        return _err("UNAUTHORIZED", "Invalid api_key.")

    # Permission model:
    # - Non-service callers can only view their own originating requests (api_key_id == authenticated key id)
    # - Service callers can view all, or filtered by api_key_id
    is_service = (ak.get("owner_type") == "service")

    if not is_service:
        if api_key_id is not None and api_key_id != ak.get("id"):
            # Not allowed to inspect others
            return _err("UNAUTHORIZED", "Not permitted to view requested records.")
        api_key_id = ak.get("id")

    # Choose accounting tool for quotas/rate limits: must be a valid enum tool.
    allowed = ak.get("allowed_endpoints") if isinstance(ak.get("allowed_endpoints"), list) else []
    acct_tool = None
    for cand in valid_tools:
        if cand in allowed:
            acct_tool = cand
            break
    if acct_tool is None:
        return _err("UNAUTHORIZED", "API key not permitted.")

    # Helper for quota/rate limit
    def _period_start(dt, typ):
        if typ == "day":
            return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, 1, tzinfo=datetime.timezone.utc)

    def _get_or_create_counter(api_key_id2, typ, pstart, tool):
        pstart_iso = pstart.isoformat()
        for r in usage:
            if r.get("api_key_id") == api_key_id2 and r.get("period_type") == typ and r.get("period_start") == pstart_iso and r.get("tool_name") == tool:
                return r
        rid = "use_" + hashlib.sha256(f"{api_key_id2}|{typ}|{pstart_iso}|{tool}".encode("utf-8")).hexdigest()[:24]
        row = {
            "id": rid,
            "api_key_id": api_key_id2,
            "period_type": typ,
            "period_start": pstart_iso,
            "tool_name": tool,
            "request_count": 0,
            "cost_units": 0,
            "last_request_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage.append(row)
        return row

    def _rate_limited(api_key_id2, rps, burst):
        if not isinstance(rps, (int, float)) or rps <= 0:
            return True
        if not isinstance(burst, int) or burst < 0:
            return True
        window = max((burst / float(rps)) if rps > 0 else 1.0, 2.0)
        cutoff = now - datetime.timedelta(seconds=window)
        recent = 0
        for r in map_requests:
            if r.get("api_key_id") != api_key_id2:
                continue
            ts = r.get("created_at")
            if not ts:
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt >= cutoff:
                recent += 1
        allowed_n = burst + int(float(rps) * window + 1e-9)
        return recent >= allowed_n

    # Create exactly one map_requests row for this invocation
    req_id = "req_" + hashlib.sha256(f"map_requests_list|{ak.get('id')}|{now_iso}|{os.getpid()}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]
    req_row = {
        "id": req_id,
        "api_key_id": ak.get("id"),
        "naver_credential_id": None,
        "tool_name": acct_tool,
        "idempotency_key": None,
        "status": "received",
        "cache_key": None,
        "client_ip": None,
        "user_agent": None,
        "request_params": {
            "tool_name": tool_name,
            "status": status,
            "api_key_id": api_key_id,
            "idempotency_key": idempotency_key,
            "created_at_gte": created_at_gte,
            "created_at_lt": created_at_lt,
            "page_size": page_size,
            "page_token": page_token,
        },
        "normalized_params": None,
        "upstream_endpoint": None,
        "upstream_status_code": None,
        "upstream_error_code": None,
        "duration_ms": None,
        "response_size_bytes": None,
        "cost_units": 0,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Enforce key status (must reject and must not increment usage counters)
    if ak.get("status") != "active":
        req_row["status"] = "rejected"
        req_row["error_message"] = "API key is not active."
        req_row["updated_at"] = now_iso
        map_requests.append(req_row)
        _save("map_requests.json", map_requests)
        return _err("UNAUTHORIZED", "API key is not active.")

    # Rate limit
    if _rate_limited(ak.get("id"), ak.get("rate_limit_rps"), ak.get("rate_limit_burst")):
        req_row["status"] = "rejected"
        req_row["error_message"] = "Rate limit exceeded."
        req_row["updated_at"] = now_iso
        map_requests.append(req_row)
        _save("map_requests.json", map_requests)
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Quota checks (request_count; cost_units=0)
    day_start = _period_start(now, "day")
    mon_start = _period_start(now, "month")
    day_counter = _get_or_create_counter(ak.get("id"), "day", day_start, acct_tool)
    mon_counter = _get_or_create_counter(ak.get("id"), "month", mon_start, acct_tool)
    if day_counter["request_count"] + 1 > int(ak.get("quota_daily_requests", 0)):
        req_row["status"] = "rejected"
        req_row["error_message"] = "Daily quota exceeded."
        req_row["updated_at"] = now_iso
        map_requests.append(req_row)
        _save("map_requests.json", map_requests)
        _save("usage_counters.json", usage)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
    if mon_counter["request_count"] + 1 > int(ak.get("quota_monthly_requests", 0)):
        req_row["status"] = "rejected"
        req_row["error_message"] = "Monthly quota exceeded."
        req_row["updated_at"] = now_iso
        map_requests.append(req_row)
        _save("map_requests.json", map_requests)
        _save("usage_counters.json", usage)
        return _err("QUOTA_EXCEEDED", "Monthly quota exceeded.")

    # Bill request for listing (cost_units=0)
    day_counter["request_count"] += 1
    day_counter["last_request_at"] = now_iso
    day_counter["updated_at"] = now_iso
    mon_counter["request_count"] += 1
    mon_counter["last_request_at"] = now_iso
    mon_counter["updated_at"] = now_iso

    # Apply filters
    def _parse_dt(s):
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    out = []
    for r in map_requests:
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if status is not None and r.get("status") != status:
            continue
        if api_key_id is not None and r.get("api_key_id") != api_key_id:
            continue
        if idempotency_key is not None and r.get("idempotency_key") != idempotency_key:
            continue
        created = r.get("created_at")
        if dt_gte is not None:
            if _parse_dt(created) < dt_gte:
                continue
        if dt_lt is not None:
            if _parse_dt(created) >= dt_lt:
                continue
        out.append(r)

    # Sort: created_at desc, id desc for stability
    out.sort(key=lambda r: (_parse_dt(r.get("created_at") or ""), r.get("id") or ""), reverse=True)

    # Pagination
    start = 0
    if page_token is not None:
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"==").decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or obj.get("v") != 1 or not isinstance(obj.get("o"), int) or obj["o"] < 0:
                return _err("VALIDATION_ERROR", "Invalid page_token.")
            start = obj["o"]
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid page_token.")
    end = start + page_size
    page = out[start:end]
    has_more = end < len(out)
    next_token = None
    if has_more:
        next_token = base64.urlsafe_b64encode(json.dumps({"v": 1, "o": end}, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    # Prepare response rows (metadata only; no payloads)
    rows = []
    for r in page:
        rows.append({
            "id": r.get("id"),
            "api_key_id": r.get("api_key_id"),
            "naver_credential_id": r.get("naver_credential_id"),
            "tool_name": r.get("tool_name"),
            "idempotency_key": r.get("idempotency_key"),
            "status": r.get("status"),
            "cache_key": r.get("cache_key"),
            "client_ip": r.get("client_ip"),
            "user_agent": r.get("user_agent"),
            "normalized_params": r.get("normalized_params"),
            "upstream_endpoint": r.get("upstream_endpoint"),
            "upstream_status_code": r.get("upstream_status_code"),
            "upstream_error_code": r.get("upstream_error_code"),
            "duration_ms": r.get("duration_ms"),
            "response_size_bytes": r.get("response_size_bytes"),
            "cost_units": r.get("cost_units"),
            "error_message": r.get("error_message"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
        })

    req_row["status"] = "succeeded"
    req_row["updated_at"] = now_iso
    req_row["duration_ms"] = int((time.time() - t0) * 1000)

    # Update api_key last_used_at
    ak["last_used_at"] = now_iso
    ak["updated_at"] = now_iso

    map_requests.append(req_row)
    _save("map_requests.json", map_requests)
    _save("usage_counters.json", usage)
    _save("api_keys.json", api_keys)

    return {
        "requests": rows,
        "page_size": page_size,
        "next_page_token": next_token,
        "total": len(out),
        "has_more": has_more,
        "request_id": req_id,
    }
